// Uretildi: ~/inventory/harness/clibuild.js — elle duzenlemeyin
(window.CG_CLI_DATA = window.CG_CLI_DATA || {})["cisco-ios"] = {"key":"cisco-ios","name":"Cisco IOS / IOS-XE / NX-OS","commands":[{"cat":"BGP","code":"show ip bgp","desc":"BGP routing tablosu: status kodlari (*/>/s/d/h/r), origin (i/e/?), next-hop, metric (MED), LocPrf, Weight, AS-Path. En temel BGP kontrol komutu","sev":"i"},{"cat":"BGP","code":"show ip bgp summary","desc":"BGP peer ozeti: Neighbor IP, AS, MsgRcvd/Sent, Up/Down, State/PfxRcd. State=Established=OK. PfxRcd=alinan prefix sayisi. Idle/Active=SORUN","sev":"i"},{"cat":"BGP","code":"show ip bgp neighbors","desc":"Tum BGP neighbor detayi: state, capabilities, timers, messages, address families. Detayli troubleshooting icin","sev":"i"},{"cat":"BGP","code":"show ip bgp neighbors <ip> advertised-routes","desc":"Bu peer'a advertise edilen route'lar. Bos ise route-map/prefix-list filtreliyor olabilir","sev":"i"},{"cat":"BGP","code":"show ip bgp neighbors <ip> received-routes","desc":"Peer'dan alinan tum route'lar (filtre oncesi). soft-reconfiguration inbound gerektirir","sev":"i"},{"cat":"BGP","code":"show ip bgp neighbors <ip> routes","desc":"Peer'dan alinan ve RIB'e KURULAN route'lar (filtre sonrasi). received-routes ile karsilastirin","sev":"i"},{"cat":"BGP","code":"show ip bgp <prefix>","desc":"Belirli prefix icin tum path'ler, best path secim sebebi, attribute'lar. Neden bu path secildi?","sev":"i"},{"cat":"BGP","code":"show ip bgp regexp <regex>","desc":"AS-path regex ile BGP tablosu filtrele. Ornek: _65000_ (AS 65000 iceren), ^65000$ (sadece AS 65000)","sev":"i"},{"cat":"BGP","code":"show ip bgp community <community>","desc":"BGP community degerine gore filtrele. Ornek: no-export, no-advertise, local-AS, <ASN>:<value>","sev":"i"},{"cat":"BGP","code":"show ip bgp dampened-paths","desc":"Flapping nedeniyle penalize edilmis route'lar. Surekli up/down olan route'lar burada gorulur","sev":"w"},{"cat":"BGP","code":"show ip bgp flap-statistics","desc":"Route flap istatistikleri: hangi prefix kac kez flap etmis. Instabil peer/link tespiti","sev":"w"},{"cat":"BGP","code":"show ip route bgp","desc":"Routing tablosunda sadece BGP ile ogrenmis route'lar. 'B' = BGP route, [20/0] = eBGP AD=20","sev":"i"},{"cat":"BGP","code":"show tcp brief","desc":"TCP session'lari (BGP TCP 179 kullanir). BGP TCP session kurulup kurulmadigini dogrulamak icin","sev":"i"},{"cat":"BGP","code":"show bgp all summary","desc":"Tum address family'ler icin BGP ozeti: IPv4 unicast, IPv6, VPNv4. Multi-AF ortaminda","sev":"i"},{"cat":"BGP","code":"router bgp <ASN>","desc":"BGP router config moduna gir. ASN: 1-65535 (2-byte) veya 1-4294967295 (4-byte AS). Tum BGP ayarlari burada","sev":"i"},{"cat":"BGP","code":"bgp router-id <ip>","desc":"BGP Router ID'yi manuel ayarla. Otomatik secim: en yuksek loopback IP, yoksa en yuksek interface IP","sev":"i"},{"cat":"BGP","code":"bgp log-neighbor-changes","desc":"Neighbor up/down olaylarini loglama. Best practice — sorun teshisinde kritik. Default olarak acik olabilir","sev":"i"},{"cat":"BGP","code":"neighbor <ip> remote-as <ASN>","desc":"BGP neighbor tanimla. ASN ayni ise iBGP, farkli ise eBGP. Her iki tarafta da tanimlanmali","sev":"i"},{"cat":"BGP","code":"neighbor <ip> update-source <interface>","desc":"BGP session icin kaynak interface. iBGP'de loopback kullanmak icin SART. Ornek: update-source Loopback0","sev":"i"},{"cat":"BGP","code":"neighbor <ip> ebgp-multihop <ttl>","desc":"eBGP'de TTL artir (default 1). Loopback uzerinden eBGP veya dogrudan bagli olmayan peer icin gerekli","sev":"i"},{"cat":"BGP","code":"neighbor <ip> password <string>","desc":"BGP session MD5 authentication. Her iki tarafta ayni olmali. Mismatch = session kurulamaz","sev":"i"},{"cat":"BGP","code":"neighbor <ip> next-hop-self","desc":"iBGP peer'lara kendi IP'ni next-hop olarak goster. iBGP'de neredeyse HER ZAMAN gerekli","sev":"i"},{"cat":"BGP","code":"neighbor <ip> route-reflector-client","desc":"Neighbor'u route-reflector client yap. iBGP full-mesh yerine RR kullanarak olceklendirme","sev":"i"},{"cat":"BGP","code":"neighbor <ip> soft-reconfiguration inbound","desc":"Inbound route'lari sakla. Policy degisikliginde session kirmadan 'clear ip bgp <ip> soft in' ile uygula","sev":"i"},{"cat":"BGP","code":"neighbor <ip> route-map <name> in","desc":"Inbound route-map filtresi. Peer'dan alinan route'lari filtrele/degistir. in/out yonu belirtin","sev":"i"},{"cat":"BGP","code":"neighbor <ip> route-map <name> out","desc":"Outbound route-map filtresi. Peer'a gonderilen route'lari filtrele/degistir","sev":"i"},{"cat":"BGP","code":"neighbor <ip> prefix-list <name> in","desc":"Inbound prefix-list filtresi. Belirli prefix'leri kabul/reddet. Route-map'ten daha basit","sev":"i"},{"cat":"BGP","code":"neighbor <ip> maximum-prefix <max> [warning%]","desc":"Peer'dan max prefix sayisi. Limit asilirsa session DROP olur! Route leak korunmasi. warning% = uyari esigi","sev":"w"},{"cat":"BGP","code":"neighbor <ip> default-originate","desc":"Bu peer'a default route (0.0.0.0/0) gonder. Routing tablosunda olmasa bile gonderir","sev":"i"},{"cat":"BGP","code":"neighbor <ip> shutdown","desc":"BGP neighbor'u admin olarak kapat. Session KOPAR. Bakim/degisiklik icin gecici kapatma","sev":"e"},{"cat":"BGP","code":"neighbor <ip> timers <hello> <hold>","desc":"Keepalive ve holddown timer. Default 60/180. Hizli tespit icin: timers 3 9","sev":"i"},{"cat":"BGP","code":"neighbor <ip> weight <0-65535>","desc":"Bu peer'dan gelen TUM route'lara weight ata. Weight en yuksek oncelik (Cisco proprietary, lokal)","sev":"i"},{"cat":"BGP","code":"network <prefix> mask <mask>","desc":"BGP'ye network advertise et. Network routing tablosunda OLMALI! Yoksa advertise edilmez","sev":"i"},{"cat":"BGP","code":"aggregate-address <prefix> <mask> summary-only","desc":"BGP aggregation: ozet route olustur ve specific'leri bastir. summary-only olmadan ikisi de gonderilir","sev":"i"},{"cat":"BGP","code":"redistribute ospf <pid> route-map <name>","desc":"OSPF'i BGP'ye redistribute et. route-map ILE kullanin — kontrolsuz redistribution tehlikeli!","sev":"w"},{"cat":"BGP","code":"redistribute static route-map <name>","desc":"Static route'lari BGP'ye redistribute et. route-map ile filtreleyin","sev":"i"},{"cat":"BGP","code":"bgp bestpath as-path multipath-relax","desc":"Farkli AS-path'li route'lar arasinda multipath (load-sharing) izin ver. ECMP icin","sev":"i"},{"cat":"BGP","code":"maximum-paths <number>","desc":"Maksimum eBGP ECMP yol sayisi. Default 1 (tek yol). Yuk dengeleme icin artirin","sev":"i"},{"cat":"BGP","code":"bgp default local-preference <value>","desc":"Default local-pref (varsayilan 100). Yuksek = tercih edilen. iBGP icinde route tercihini etkiler","sev":"i"},{"cat":"BGP","code":"distance bgp <external> <internal> <local>","desc":"BGP AD (Administrative Distance). Default: eBGP=20, iBGP=200, local=200","sev":"i"},{"cat":"BGP","code":"debug ip bgp","desc":"Genel BGP debug: tum BGP olaylari. Cok yogun cikti uretir — production'da DIKKATLI kullanin! Belirli neighbor icin: debug ip bgp <ip>","sev":"e"},{"cat":"BGP","code":"debug ip bgp <ip> updates","desc":"Belirli neighbor icin UPDATE mesajlarini debug et. Ornek cikti: 'BGP(0): 10.1.1.2 rcvd UPDATE w/ attr: nexthop 10.1.1.2, origin i, localpref 100, metric 0, path 65001' ve 'BGP(0): 10.1.1.2 rcvd 192.168.1.0/24'. Route alinimi/gonderimini izlemek icin","sev":"e"},{"cat":"BGP","code":"debug ip bgp updates","desc":"TUM neighbor'lar icin UPDATE debug. Her gelen/giden UPDATE mesajini gosterir. Ornek: 'BGP(0): 10.0.0.1 send UPDATE (format) 172.24.0.0/16, next 10.0.0.2, metric 0, path 65002'. Yogun trafik ortaminda CPU tehlikesi!","sev":"e"},{"cat":"BGP","code":"debug ip bgp keepalives","desc":"BGP keepalive mesajlarini debug et. Default: her 60 sn bir keepalive gonderilir. Ornek cikti: 'BGP: 10.1.1.2 sending KEEPALIVE' ve 'BGP: 10.1.1.2 received KEEPALIVE'. Hold timer expired sorunlarinda kullanin","sev":"e"},{"cat":"BGP","code":"debug ip bgp events","desc":"BGP olay debug: state transition'lar, session kurulma/kapanma olaylari. Ornek: 'BGP: 10.1.1.2 went from Idle to Connect' veya 'BGP: 10.1.1.2 went from OpenSent to Established'. FSM sorunlari icin","sev":"e"},{"cat":"BGP","code":"debug ip bgp notifications","desc":"BGP NOTIFICATION mesajlarini debug et. Session kapanma sebeplerini gosterir. Ornek: '%BGP-3-NOTIFICATION: sent to neighbor 10.1.1.2 4/0 (hold time expired) 0 bytes'. Error Code/Subcode gosterir","sev":"e"},{"cat":"BGP","code":"debug ip bgp dampening","desc":"BGP route dampening debug. Flapping route'larin penalize/suppress/reuse durumlarini izler. Suppress=2000, Reuse=750, HalfLife=15dk, MaxSuppress=60dk","sev":"e"},{"cat":"BGP","code":"debug ip bgp <ip> in","desc":"Belirli neighbor'dan GELEN tum BGP mesajlarini debug et. Sadece inbound trafik gorulur","sev":"e"},{"cat":"BGP","code":"debug ip bgp <ip> out","desc":"Belirli neighbor'a GIDEN tum BGP mesajlarini debug et. Sadece outbound trafik gorulur","sev":"e"},{"cat":"BGP","code":"! BGP Notification Code 1: Message Header Error","desc":"Subcode 1=Connection Not Synchronized, 2=Bad Message Length, 3=Bad Message Type. TCP session bozuk veya BGP mesaj formati hatali. Cozum: clear ip bgp <ip> ile session restart","sev":"w"},{"cat":"BGP","code":"! BGP Notification Code 2: OPEN Message Error","desc":"Subcode 1=Unsupported Version, 2=Bad Peer AS (AS numarasi uyusmuyor!), 3=Bad BGP Identifier (ayni Router ID!), 4=Unsupported Optional Parameter, 5=Authentication Failure (MD5 mismatch!), 6=Unacceptable Hold Time. En yaygin: 2/2 ve 2/5","sev":"w"},{"cat":"BGP","code":"! BGP Notification Code 3: UPDATE Message Error","desc":"Subcode 1=Malformed Attr List, 2=Unrecognized Well-known Attr, 3=Missing Well-known Attr, 4=Attr Flags Error, 5=Attr Length Error, 6=Invalid ORIGIN, 7=AS Routing Loop, 8=Invalid NEXT_HOP, 9=Optional Attr Error, 10=Invalid Network, 11=Malformed AS_PATH","sev":"w"},{"cat":"BGP","code":"! BGP Notification Code 4: Hold Timer Expired","desc":"Hold timer suresi doldu (default 180sn). Keepalive alinmadi. Sebepler: 1) Fiziksel link sorunu, 2) CPU asiri yuku — keepalive gonderilemiyor, 3) MTU sorunu — paketler dusuyor, 4) Unidirectional link. Debug: debug ip bgp keepalives","sev":"e"},{"cat":"BGP","code":"! BGP Notification Code 5: Finite State Machine Error","desc":"BGP FSM beklenmeyen bir olay aldi. Genellikle yazilim bug veya race condition. Cozum: IOS guncelle, clear ip bgp","sev":"e"},{"cat":"BGP","code":"! BGP Notification Code 6: Cease","desc":"Subcode 1=Max Prefixes Reached (prefix limiti asildi!), 2=Administrative Shutdown (neighbor shutdown), 3=Peer De-configured (neighbor silindi), 4=Administrative Reset (clear ip bgp), 5=Connection Rejected, 6=Other Config Change, 7=Connection Collision Resolution, 8=Out of Resources","sev":"w"},{"cat":"BGP","code":"! BGP Best Path Selection Sirasi","desc":"1) WEIGHT (en yuksek, Cisco proprietary, lokal, default 0) → 2) LOCAL_PREFERENCE (en yuksek, iBGP icinde, default 100) → 3) Locally Originated (network/redistribute/aggregate) → 4) AS_PATH (en kisa) → 5) ORIGIN (IGP < EGP < incomplete) → 6) MED (en dusuk, AS'ler arasi) → 7) eBGP > iBGP → 8) IGP Metric (next-hop'a en yakin) → 9) Oldest Path → 10) Router ID (en dusuk) → 11) Neighbor IP (en dusuk)","sev":"i"},{"cat":"BGP","code":"! BGP Status Kodlari (show ip bgp)","desc":"* = valid (gecerli), > = best (en iyi secilmis), s = suppressed (bastirili, aggregation), d = damped (flapping nedeniyle cezali), h = history (gecmis, withdraw edilmis), r = RIB-failure (routing tablosuna kurulamadi, AD sorunu), S = stale (bayat). Origin: i = IGP, e = EGP, ? = incomplete (redistribute)","sev":"i"},{"cat":"BGP","code":"! BGP Neighbor State: Idle","desc":"Baslangic durumu. BGP henuz TCP baglantisi denemiyor. Sebepler: 1) Neighbor IP'ye route yok, 2) Onceki baglanti reddedildi (ConnectRetryTimer=60sn, katlanarak artar), 3) update-source yanlis. Kontrol: show ip route <neighbor-ip>","sev":"w"},{"cat":"BGP","code":"! BGP Neighbor State: Connect","desc":"TCP 3-way handshake baslatildi, bekliyor. Yuksek IP adresli taraf baglantiya sahip olur. TCP port 179. Connect'te takilirsa: ACL/firewall TCP 179 engelliyor, veya fiziksel baglanti sorunu","sev":"w"},{"cat":"BGP","code":"! BGP Neighbor State: Active","desc":"DIKKAT: Active = 'aktif calisiyor' DEMEK DEGIL! TCP baglantisi BASARISIZ oldu, yeniden deniyor. Sebepler: 1) TCP connectivity yok, 2) ACL port 179 engelliyor, 3) Neighbor tarafinda BGP tanimli degil, 4) update-source hatasi. En yaygin BGP sorunu!","sev":"e"},{"cat":"BGP","code":"! BGP Neighbor State: OpenSent","desc":"TCP kuruldu, OPEN mesaji gonderildi, karsi tarafin OPEN'i bekleniyor. Kontroller: BGP version eslesmeli, source IP dogru olmali, AS numarasi eslesmeli, Router ID benzersiz olmali, MD5 password eslesmeli. OpenSent'te takilirsa: config mismatch","sev":"w"},{"cat":"BGP","code":"! BGP Neighbor State: OpenConfirm","desc":"OPEN mesajlari dogrulandi, KEEPALIVE bekleniyor. Hold Time muzakere edilir (dusuk deger secilir). Bu durumda takilirsa: network latency Hold Timer'i asiriyor, veya NOTIFICATION hatasi alindi","sev":"w"},{"cat":"BGP","code":"! BGP Neighbor State: Established","desc":"BGP session BASARIYLA kuruldu! Route degisimi (UPDATE) basliyor. show ip bgp summary'de PfxRcd=sayi gorulmeli. UPDATE/KEEPALIVE ile Hold Timer sifirlanir. Hold Timer dolarsa Idle'a doner. Established ama 0 prefix ise: route-map/filter kontrol edin","sev":"i"},{"cat":"BGP","code":"! show ip bgp summary Alan Aciklamasi","desc":"Neighbor=Peer IP | V=BGP versiyon (4) | AS=Neighbor ASN | MsgRcvd=alinan mesaj | MsgSent=gonderilen mesaj | TblVer=tablo versiyonu (router TblVer ile esmeli) | InQ=input kuyrugu (0 olmali) | OutQ=output kuyrugu (0 olmali, >0=tikaniklik) | Up/Down=sure | State/PfxRcd=state veya alinan prefix sayisi","sev":"i"},{"cat":"BGP","code":"! show ip bgp neighbors Onemli Alanlar","desc":"BGP state = Established, up for HH:MM:SS | Last read/write = son mesaj zamani | Hold time is 180, keepalive interval is 60 | Notification mesajlari: son error code/subcode | Connections established/dropped = kac kez kuruldu/koptu (yuksekse instabil!) | Prefix received/sent sayilari","sev":"i"},{"cat":"BGP","code":"clear ip bgp *","desc":"TUM BGP session'lari reset! Trafik KESILIR! Production'da KULLANMAYIN. Belirli peer icin: clear ip bgp <ip>","sev":"e"},{"cat":"BGP","code":"clear ip bgp <ip> soft in","desc":"Belirli peer icin inbound soft reset. Session KOPMAZ, sadece route'lar yeniden islenir. En guvenli yontem","sev":"w"},{"cat":"BGP","code":"clear ip bgp <ip> soft out","desc":"Belirli peer icin outbound soft reset. Peer'a route'lari yeniden gonderir. Baglanti kopmaz","sev":"w"},{"cat":"OSPF","code":"show ip ospf neighbor","desc":"OSPF neighbor tablosu: Neighbor ID, Priority, State (Full/Init/2Way/Down), Dead Time, Address, Interface. Full=OK, diger=SORUN","sev":"i"},{"cat":"OSPF","code":"show ip ospf neighbor detail","desc":"Detayli neighbor bilgisi: state transition sayisi, DR/BDR, options, retransmit sayisi. Adjacency sorunu teshisi","sev":"i"},{"cat":"OSPF","code":"show ip ospf interface","desc":"OSPF interface'leri: Area, Process ID, Router ID, Cost, State (DR/BDR/DROther), Timer'lar, Neighbor sayisi, Network Type","sev":"i"},{"cat":"OSPF","code":"show ip ospf interface brief","desc":"OSPF interface ozeti: interface, PID, area, cost, state, neighbors. Hizli genel bakis","sev":"i"},{"cat":"OSPF","code":"show ip ospf database","desc":"LSDB ozeti: Router LSA (Type-1), Network (Type-2), Summary (Type-3), ASBR Summary (Type-4), External (Type-5), NSSA (Type-7)","sev":"i"},{"cat":"OSPF","code":"show ip ospf database external","desc":"Type-5 External LSA'lar — baska routing protocol'den redistribute edilmis route'lar","sev":"i"},{"cat":"OSPF","code":"show ip ospf","desc":"OSPF process bilgisi: Router ID, area listesi, SPF hesaplama sayisi/zamani, reference bandwidth","sev":"i"},{"cat":"OSPF","code":"show ip route ospf","desc":"Sadece OSPF route'lar: O=intra-area, O IA=inter-area, O E1/E2=external, O N1/N2=NSSA","sev":"i"},{"cat":"OSPF","code":"router ospf <process-id>","desc":"OSPF process baslat. process-id yerel anlam tasir (1-65535). Komsu router'da farkli olabilir ama area ayni olmali","sev":"i"},{"cat":"OSPF","code":"router-id <ip>","desc":"OSPF Router ID'yi manuel ayarla. Best practice: Loopback IP kullanin. Degisiklik icin clear ip ospf process gerekir","sev":"i"},{"cat":"OSPF","code":"network <ip> <wildcard> area <area-id>","desc":"OSPF'i interface'lerde etkinlestir. Wildcard mask ile eslesyen interface'ler belirtilen area'ya atanir","sev":"i"},{"cat":"OSPF","code":"ip ospf <pid> area <area-id>","desc":"Interface uzerinde dogrudan OSPF etkinlestir. Modern yontem — network komutundan daha net ve kontrollü","sev":"i"},{"cat":"OSPF","code":"passive-interface <interface>","desc":"Interface'den OSPF hello gonderme. Connected network yine advertise edilir ama neighbor olunmaz. LAN portlari icin","sev":"i"},{"cat":"OSPF","code":"passive-interface default","desc":"Tum interface'leri passive yap. Sonra no passive-interface ile sadece gerekenleri ac. Guvenlik best practice","sev":"i"},{"cat":"OSPF","code":"default-information originate always","desc":"OSPF'e default route advertise et. 'always' = routing tablosunda olmasa bile gonder. ABR/ASBR'da kullanilir","sev":"i"},{"cat":"OSPF","code":"area <id> stub","desc":"Stub area: Type-5 External LSA'lari engeller, ABR default route enjekte eder. Internet erisimi olmayan area'lar icin","sev":"i"},{"cat":"OSPF","code":"area <id> stub no-summary","desc":"Totally stubby area: Type-3 ve Type-5 engeller, sadece default route kalir. En cok kisitlama. ABR'da tanimlanir","sev":"i"},{"cat":"OSPF","code":"area <id> nssa","desc":"NSSA (Not-So-Stubby Area): Type-5 engeller ama Type-7 ile redistribution izin verir. External kaynak olan stub area","sev":"i"},{"cat":"OSPF","code":"area <id> range <prefix> <mask>","desc":"ABR'da inter-area route summarization. Birden fazla specific'i tek ozet route ile gonderir. Routing tablosu kucultme","sev":"i"},{"cat":"OSPF","code":"auto-cost reference-bandwidth <Mbps>","desc":"OSPF cost hesaplamasi icin referans BW. Default 100Mbps = GigE cost 1. 10000 veya 100000 yapin (10G/100G icin)","sev":"i"},{"cat":"OSPF","code":"ip ospf cost <1-65535>","desc":"Interface OSPF cost'unu manuel ayarla. Auto-cost yerine belirli deger atama. Dusuk cost = tercih edilen yol","sev":"i"},{"cat":"OSPF","code":"ip ospf priority <0-255>","desc":"DR/BDR election priority. 0 = asla DR olma. Default 1. En yuksek priority DR olur. Tie = en yuksek Router ID","sev":"i"},{"cat":"OSPF","code":"ip ospf network point-to-point","desc":"Network tipini p2p yap. DR/BDR election ATLANIR, daha hizli adjacency. /30 veya /31 linkler icin onerilen","sev":"i"},{"cat":"OSPF","code":"ip ospf authentication message-digest","desc":"Interface'de MD5 authentication etkinlestir. Her iki tarafta ayni key olmali. Guvenlik best practice","sev":"i"},{"cat":"OSPF","code":"ip ospf mtu-ignore","desc":"MTU mismatch'i gormezden gel. Exstart/Exchange'de takilma sorununu cozer. Gercek MTU sorununu maskeleyebilir!","sev":"w"},{"cat":"OSPF","code":"redistribute eigrp <AS> subnets route-map <name>","desc":"EIGRP'yi OSPF'e redistribute et. 'subnets' kelimesi KRITIK — olmadan sadece classful route gider!","sev":"w"},{"cat":"OSPF","code":"clear ip ospf process","desc":"OSPF process'i sifirla. Adjacency'ler KOPAR ve yeniden kurulur. Router-ID degisikligi sonrasi gerekir","sev":"e"},{"cat":"OSPF","code":"debug ip ospf adj","desc":"OSPF adjacency debug: neighbor state degisimlerini, DR/BDR election'i, authentication hatalarini gosterir. En onemli OSPF debug komutu. Ornek cikti: 'Rcv DBD from 10.1.1.2 seq 0x2A opt 0x52 flag 0x7 len 32 mtu 1500 state EXSTART'","sev":"w"},{"cat":"OSPF","code":"debug ip ospf hello","desc":"OSPF hello paket debug: gonderilen/alinan hello'lar, timer mismatch, subnet mismatch, area mismatch gosterir. Ornek hata: 'Mismatched hello parameters from 10.1.1.2 Dead R 11 C 40, Hello R 10 C 10'","sev":"w"},{"cat":"OSPF","code":"debug ip ospf events","desc":"OSPF olay debug: SPF hesaplama, neighbor state degisimi, interface degisiklikleri. Ornek: 'ospf_event: neighbor 10.1.1.2 changed from LOADING to FULL'","sev":"w"},{"cat":"OSPF","code":"debug ip ospf spf","desc":"SPF algoritma debug: SPF hesaplama tetiklenmesi, sure, LSA degisiklikleri. Ornek: 'Starting SPF, areas 1, trigger LSA: area 0 type 1 lsa-id 10.1.1.1 adv-rtr 10.1.1.1'. Sik SPF = instability!","sev":"w"},{"cat":"OSPF","code":"debug ip ospf lsa-generation","desc":"LSA uretim debug: hangi LSA'lar uretiliyor, neden. Router LSA, Network LSA, Summary LSA uretimini gosterir. Sik LSA uretimi = flapping interface veya redistribution sorunu","sev":"w"},{"cat":"OSPF","code":"debug ip ospf packet","desc":"OSPF paket debug: tum OSPF paketleri (Hello, DBD, LSR, LSU, LSAck). Yuksek trafik uretir — dikkatli kullanin! 'OSPF: rcv. v:2 t:1 l:48 rid:10.1.1.2 aid:0.0.0.0 chk:xxxx aut:0 apts:0 from FastEthernet0/0'","sev":"e"},{"cat":"OSPF","code":"debug ip ospf flooding","desc":"OSPF flooding debug: LSA flooding islemi, hangi interface'lerden flood ediliyor. LSA propagation sorunlarinda kullanin","sev":"w"},{"cat":"OSPF","code":"show ip ospf database summary","desc":"Type-3 Summary LSA'lar: inter-area route'lar. ABR tarafindan uretilir. 'Adv Router is not-reachable' mesaji = ABR'a ulasim sorunu","sev":"i"},{"cat":"OSPF","code":"show ip ospf database nssa-external","desc":"Type-7 NSSA External LSA'lar. NSSA area'daki redistribute edilmis route'lar. ABR'da Type-5'e cevirilir","sev":"i"},{"cat":"OSPF","code":"show ip ospf database router","desc":"Type-1 Router LSA'lar: her OSPF router'in kendi linkleri. Link Count, Link Type (Stub/Transit/P2P), Metric bilgileri","sev":"i"},{"cat":"OSPF","code":"show ip ospf database network","desc":"Type-2 Network LSA'lar: DR tarafindan multi-access networklerde uretilir. Attached Router listesi icerir","sev":"i"},{"cat":"OSPF","code":"show ip ospf statistics","desc":"SPF istatistikleri: SPF calisma sayisi, son SPF suresi, SPF delay. Sik SPF = network instability","sev":"i"},{"cat":"OSPF","code":"show ip ospf border-routers","desc":"ABR ve ASBR'larin listesi: Router ID, cost, next-hop. Type-3/Type-5 LSA sorunlarinda ABR/ASBR erisimi kontrol","sev":"i"},{"cat":"OSPF","code":"show ip ospf virtual-links","desc":"Virtual link durumu: UP/DOWN, transit area, hello/dead timer, authentication. Area 0 connectivity sorunu teshisi","sev":"i"},{"cat":"OSPF","code":"show ip ospf database database-summary","desc":"Her area icin LSA sayisi ozeti: Router, Network, Summary Net, Summary ASBR, External LSA sayilari. Database overload tespiti","sev":"i"},{"cat":"OSPF","code":"router ospf <pid>\n max-lsa <number>","desc":"OSPF LSDB overload protection: max non-self-generated LSA sayisi. Asildiginda adjacency'ler dusurulur. Default (IOS XE 17.11+): 50000","sev":"w"},{"cat":"OSPF","code":"router ospf <pid>\n max-lsa <number> <threshold-pct> warning-only","desc":"OSPF LSA limit — warning-only: adjacency dusurulmez, sadece syslog uyarisi. Monitoring icin. Ornek: max-lsa 30000 75 warning-only","sev":"i"},{"cat":"OSPF","code":"area <id> filter-list prefix <name> in","desc":"ABR'da Type-3 LSA filtreleme: belirli prefix'lerin area'ya girmesini engeller. Inter-area route filtreleme","sev":"i"},{"cat":"OSPF","code":"area <id> filter-list prefix <name> out","desc":"ABR'da Type-3 LSA filtreleme: belirli prefix'lerin area'dan cikmasini engeller","sev":"i"},{"cat":"OSPF","code":"distribute-list prefix <name> out <protocol>","desc":"ASBR'da Type-5 LSA filtreleme: redistribute edilen route'lari filtreler. 'out' = external LSA filtresi","sev":"i"},{"cat":"EIGRP","code":"show ip eigrp neighbors","desc":"EIGRP neighbor listesi: Handle, Address, Interface, Hold time, SRTT (ms), RTO, Q Cnt, Seq Num. Q Cnt>0 = kuyruk sorunu","sev":"i"},{"cat":"EIGRP","code":"show ip eigrp neighbors detail","desc":"Detayli neighbor bilgisi: yazilim versiyonu, retransmit istatistikleri, uptime. Versiyon uyumsuzlugu tespiti","sev":"i"},{"cat":"EIGRP","code":"show ip eigrp topology","desc":"EIGRP topoloji tablosu: Successor ve Feasible Successor'lar, FD (Feasible Distance), AD (Advertised Distance) degerleri","sev":"i"},{"cat":"EIGRP","code":"show ip eigrp topology all-links","desc":"Feasibility condition'i karsilamayan route'lar dahil TUM route'lar. Neden FS olmadigini anlamak icin","sev":"i"},{"cat":"EIGRP","code":"show ip eigrp interfaces","desc":"EIGRP etkin interface'ler: peer sayisi, xmit-queue, pending routes, SRTT ortalamasi. Interface bazli EIGRP durumu","sev":"i"},{"cat":"EIGRP","code":"show ip eigrp traffic","desc":"EIGRP paket istatistikleri: Hello, Update, Query, Reply, ACK gonderilen/alinan sayilari. Query storm tespiti","sev":"i"},{"cat":"EIGRP","code":"show ip route eigrp","desc":"Sadece EIGRP route'lar: D=internal (AD 90), D EX=external (AD 170). Metric degerleri ve next-hop","sev":"i"},{"cat":"EIGRP","code":"router eigrp <AS-number>","desc":"EIGRP config moduna gir. AS nummarasi (1-65535) TUM EIGRP router'larda AYNI olmali! Farkli AS = neighbor olunamaz","sev":"i"},{"cat":"EIGRP","code":"eigrp router-id <ip>","desc":"EIGRP Router ID'yi manuel ayarla. Best practice: Loopback IP","sev":"i"},{"cat":"EIGRP","code":"network <ip> <wildcard>","desc":"EIGRP'yi eslesyen interface'lerde etkinlestir ve network'u advertise et. Wildcard mask ile ince ayar","sev":"i"},{"cat":"EIGRP","code":"no auto-summary","desc":"Classful auto-summarization'i kapat. IOS 15+ default kapali. Eski IOS'ta MUTLAKA kapatin!","sev":"i"},{"cat":"EIGRP","code":"passive-interface <interface>","desc":"Hello gondermeyi durdur. Connected network advertise edilir ama neighbor olunmaz","sev":"i"},{"cat":"EIGRP","code":"variance <multiplier>","desc":"Unequal-cost load balancing. Default 1 (sadece equal). 2 = FD'nin 2 katina kadar olan FS'ler de kullanilir","sev":"i"},{"cat":"EIGRP","code":"maximum-paths <1-32>","desc":"ECMP yol sayisi. Default platforma gore degisir (4 veya 16). Yuk dengeleme icin","sev":"i"},{"cat":"EIGRP","code":"redistribute ospf <pid> metric <bw> <delay> <rel> <load> <mtu>","desc":"OSPF'i EIGRP'ye redistribute et. Seed metric ZORUNLU — yoksa route gorunmez! Ornek: metric 100000 100 255 1 1500","sev":"w"},{"cat":"EIGRP","code":"ip summary-address eigrp <AS> <prefix> <mask>","desc":"Interface uzerinde EIGRP manual summarization. Specific'ler bastirillir, ozet gonderilir","sev":"i"},{"cat":"EIGRP","code":"stub connected static","desc":"EIGRP stub yapillandirmasi: query almaz, sadece connected ve static advertise eder. Spoke router'larda kullanilir","sev":"i"},{"cat":"EIGRP","code":"ip authentication mode eigrp <AS> md5","desc":"Interface'de EIGRP MD5 authentication etkinlestir. Guvenlik best practice","sev":"i"},{"cat":"EIGRP","code":"distance eigrp <internal> <external>","desc":"EIGRP AD (Administrative Distance). Default: internal=90, external=170","sev":"i"},{"cat":"EIGRP","code":"ip authentication key-chain eigrp <AS> <keychain-name>","desc":"Interface'de EIGRP authentication icin key-chain ata. key-chain onceden tanimlanmali. Iki tarafta key ID ve key string AYNI olmali","sev":"i"},{"cat":"EIGRP","code":"eigrp log-neighbor-changes","desc":"Neighbor up/down olaylarini logla. SIA ve neighbor sorunlari icin KRITIK. Best practice: her zaman etkinlestirin. Ornek log: '%DUAL-5-NBRCHANGE: EIGRP-IPv4 1: Neighbor 10.1.1.2 (Gi0/0) is up'","sev":"i"},{"cat":"EIGRP","code":"timers active-time <minutes|disabled>","desc":"SIA (Stuck-in-Active) timer suresi. Default 3 dakika (180 sn). 90 sn'de SIA-Query gonderilir, 180 sn'de neighbor dusurulur. 'disabled' = sinirsiz bekle (onerILMEZ)","sev":"w"},{"cat":"EIGRP","code":"debug eigrp packets","desc":"Tum EIGRP paketlerini debug et: Hello, Update, Query, Reply, ACK. Cok yogun cikti! Ornek: 'EIGRP: Received HELLO on Gi0/0 nbr 10.1.1.2'. Belirli paket tipi icin: debug eigrp packets hello","sev":"e"},{"cat":"EIGRP","code":"debug eigrp packets hello","desc":"Sadece EIGRP Hello paketlerini debug et. Neighbor olusmadiginda ilk kontrol noktasi. Ornek: 'EIGRP: Gi0/0: Hello received from 10.1.1.2 with K-values K1=1, K2=0, K3=1, K4=0, K5=0'","sev":"e"},{"cat":"EIGRP","code":"debug eigrp packets query","desc":"EIGRP Query paketlerini debug et. Route kaybedildiginde gonderilen sorgulari izlemek icin. Query storm tespitinde kullanin","sev":"e"},{"cat":"EIGRP","code":"debug eigrp packets reply","desc":"EIGRP Reply paketlerini debug et. Query'lere gelen yanitlari izler. SIA sorunlarinda reply gelip gelmedigini dogrulamak icin","sev":"e"},{"cat":"EIGRP","code":"debug eigrp packets update","desc":"EIGRP Update paketlerini debug et. Route degisikliklerinin gonderim/alimini izlemek icin. Hangi route'larin dagitildigini gorursunuz","sev":"e"},{"cat":"EIGRP","code":"debug eigrp packets terse","desc":"EIGRP paketlerini kisaltilmis formatta debug et. Hello paketlerini GOSTERMEZ — daha az cikti uretir. Production'da debug eigrp packets yerine bunu tercih edin","sev":"e"},{"cat":"EIGRP","code":"debug eigrp packets SIAquery SIAreply","desc":"Sadece SIA-Query ve SIA-Reply paketlerini debug et. SIA troubleshooting icin. SIA-Query 90 sn'de gonderilir, SIA-Reply gelmezse 180 sn'de neighbor dusurulur","sev":"e"},{"cat":"EIGRP","code":"debug ip eigrp","desc":"EIGRP routing olaylari debug: route hesaplamalari, DUAL FSM, metric degisiklikleri. Ornek: 'IP-EIGRP(0): 10.0.0.0/24 - do advertise out Gi0/0'. Update icerigini gosterir","sev":"e"},{"cat":"EIGRP","code":"debug ip eigrp notifications","desc":"EIGRP bildirim olaylari debug: network degisiklikleri, topoloji olaylari. Daha az yogun cikti, production'da nispeten guvenli","sev":"e"},{"cat":"EIGRP","code":"debug eigrp neighbors","desc":"EIGRP neighbor olaylari debug: adjacency kurulma/kopma, hold timer, hello alim/gonderim. Neighbor flap sorunlarinda kullanin","sev":"e"},{"cat":"EIGRP","code":"! EIGRP Hata: K-Value Mismatch","desc":"Mesaj: '%DUAL-5-NBRCHANGE: IP-EIGRP(0) 1: Neighbor 10.1.1.2 (Gi0/0) is down: K-value mismatch'. Sebep: metric weights farkli (default K1=1,K2=0,K3=1,K4=0,K5=0). Kontrol: show ip protocols → metric weights. Cozum: her iki tarafta ayni metric weights tanimlayin","sev":"e"},{"cat":"EIGRP","code":"! EIGRP Hata: AS Number Mismatch","desc":"Hic hata mesaji GORULMEZ! Neighbor olusmuyor ama log'da hata yok. Sebep: router eigrp <AS> numaralari farkli. EIGRP'de AS numarasi OSPF process-id gibi DEGIL — eslesmeli! Kontrol: show ip protocols → Routing Protocol is eigrp <AS>","sev":"e"},{"cat":"EIGRP","code":"! EIGRP Hata: Stuck-in-Active (SIA)","desc":"Mesaj: '%DUAL-3-SIA: Route 10.0.0.0/24 stuck-in-active state in IP-EIGRP 1'. Sebep: Query'ye 180 sn icinde Reply alinmadi. Nedenler: 1) Neighbor CPU overload, 2) Unidirectional link, 3) Query scope cok genis. Cozum: stub router, summarization, query scope daraltma","sev":"e"},{"cat":"EIGRP","code":"! EIGRP Hata: Authentication Failure","desc":"Mesaj: 'EIGRP: Gi0/0: ignored packet from 10.1.1.2, opcode = 1 (missing authentication or key-chain missing)'. Sebep: 1) Bir tarafta auth var digerde yok, 2) Key string uyusmuyor, 3) Key-chain tanimli degil. Kontrol: show key chain, debug eigrp packets","sev":"e"},{"cat":"EIGRP","code":"! EIGRP Hata: Uncommon Subnet","desc":"Mesaj: 'IP-EIGRP(0) 1: Neighbor 10.1.1.2 not on common subnet for Gi0/0'. Sebep: Interface IP adresleri farkli subnet'te. Cozum: Her iki tarafin IP/mask'ini kontrol edin — ayni subnet'te olmali","sev":"e"},{"cat":"EIGRP","code":"! EIGRP Hata: Retry Limit Exceeded","desc":"Mesaj: '%DUAL-5-NBRCHANGE: IP-EIGRP(0) 1: Neighbor 10.1.1.2 (Gi0/0) is down: retry limit exceeded'. Sebep: Reliable paketler (Update/Query/Reply) 16 kez tekrar gonderildi ama ACK alinmadi. Genellikle MTU veya interface sorunu","sev":"e"},{"cat":"EIGRP","code":"! show ip eigrp topology Durum Kodlari","desc":"P=Passive (iyi, stabil), A=Active (kotu, route kaybedildi, query gonderiliyor), U=Update isleniyor, Q=Query isleniyor, R=Reply isleniyor, r=Reply Status (query izleme), s=SIA Status (stuck-in-active tehlikesi!). Passive=HEDEF DURUM","sev":"i"},{"cat":"EIGRP","code":"! show ip eigrp topology Alan Aciklamasi","desc":"Ornek: 'P 10.0.0.0/24, 1 successors, FD is 409600 via 10.1.1.2 (409600/128256), Gi0/0'. P=Passive | 1 successors=1 en iyi yol | FD=409600 Feasible Distance (bu router'dan hedefe) | via=next-hop | (409600/128256)=(FD/RD) | RD=Reported Distance (neighbor'un hedefe metric'i) | Gi0/0=cikis interface","sev":"i"},{"cat":"EIGRP","code":"show ip eigrp topology active","desc":"Sadece ACTIVE durumdaki route'lari goster: hangi route'lar icin query gonderilmis, kac reply bekleniyor, ne kadar suredir active. SIA tehlikesini onceden tespit icin","sev":"w"},{"cat":"EIGRP","code":"show ip eigrp topology <prefix>","desc":"Belirli bir prefix icin detayli topoloji bilgisi: tum yollar, FD, RD, successor/feasible successor durumu. Route secim sorunlarinda kullanin","sev":"i"},{"cat":"Static Route","code":"ip route <prefix> <mask> <next-hop>","desc":"Statik route: next-hop IP ile. AD default 1. Floating static icin daha yuksek AD verin","sev":"i"},{"cat":"Static Route","code":"ip route <prefix> <mask> <exit-interface>","desc":"Statik route: cikis interface ile. P2P linkler icin uygun. Broadcast networklerde proxy-ARP gerektirir","sev":"i"},{"cat":"Static Route","code":"ip route 0.0.0.0 0.0.0.0 <next-hop>","desc":"Default route (gateway of last resort). Internet cikisi icin. 'ip default-gateway' L2 switchlerde kullanilir","sev":"i"},{"cat":"Static Route","code":"ip route <prefix> <mask> <next-hop> <AD>","desc":"Floating static route: yuksek AD (ornek 200) ile yedek route. Primary route duserse devreye girer","sev":"i"},{"cat":"Static Route","code":"ip route <prefix> <mask> <next-hop> track <obj>","desc":"Track objesine bagli static route. Track DOWN olursa route otomatik kalkar. IP SLA ile birlikte kullanilir","sev":"i"},{"cat":"IP SLA","code":"ip sla <number>","desc":"IP SLA probe konfigurasyonuna gir. Number: 1-2147483647. ICMP echo, TCP connect, HTTP GET gibi probe'lar tanimlanir","sev":"i"},{"cat":"IP SLA","code":"icmp-echo <dest-ip> source-interface <intf>","desc":"ICMP echo (ping) probe tanimla. dest-ip = izlenecek hedef. source-interface = ping kaynak interface'i","sev":"i"},{"cat":"IP SLA","code":"frequency <seconds>","desc":"Probe gonderme sikligi (saniye). Default 60. Dusuk deger = hizli tespit ama daha cok trafik","sev":"i"},{"cat":"IP SLA","code":"timeout <milliseconds>","desc":"Probe timeout suresi (ms). Default 5000. timeout < frequency olmali","sev":"i"},{"cat":"IP SLA","code":"ip sla schedule <number> life forever start-time now","desc":"SLA probe'u hemen baslat ve surekli calistir. life forever = sonsuza kadar. start-time now = simdi baslat","sev":"i"},{"cat":"IP SLA","code":"show ip sla statistics","desc":"SLA sonuclari: Return code (OK/Timeout/Busy/Error), RTT, son calisma zamani. Timeout = hedef ulasilamaz","sev":"i"},{"cat":"IP SLA","code":"show ip sla configuration","desc":"Tum SLA probe konfigurasyonlari","sev":"i"},{"cat":"Track","code":"track <obj> ip sla <number> reachability","desc":"IP SLA sonucuna bagli track objesi. SLA OK ise track UP, SLA fail ise track DOWN. Static route/HSRP ile kullanilir","sev":"i"},{"cat":"Track","code":"track <obj> interface <intf> line-protocol","desc":"Interface line-protocol durumunu track et. Interface down olursa track DOWN olur","sev":"i"},{"cat":"Track","code":"track <obj> list boolean and","desc":"Boolean AND track listesi. Tum object'ler UP ise track UP. Herhangi biri DOWN = track DOWN. Cift IP SLA kontrolu icin","sev":"i"},{"cat":"Track","code":"object <track-obj>","desc":"Track list icinde: alt track objesini ekle. Boolean and/or listesine uye yapilir","sev":"i"},{"cat":"Track","code":"show track","desc":"Tum track objeleri ve durumları: UP/DOWN, change count, last change time","sev":"i"},{"cat":"EEM","code":"event manager applet <name>","desc":"EEM (Embedded Event Manager) applet olustur. Event'e dayali otomatik aksiyon: track down olunca email gonder, konfig degistir vs.","sev":"i"},{"cat":"EEM","code":"event track <obj> state down","desc":"Tetikleyici: track objesi DOWN oldugunda. state up ile UP oldugunda da tetiklenebilir","sev":"i"},{"cat":"EEM","code":"action 1.0 syslog msg \"Track DOWN - failover tetiklendi\"","desc":"EEM aksiyonu: syslog mesaji yaz. action X.Y = sira numarasi. Birden fazla action tanimlanabilir","sev":"i"},{"cat":"EEM","code":"action 2.0 cli command \"enable\"","desc":"EEM aksiyonu: CLI komutu calistir. enable > conf t > herhangi bir IOS komutu zinciri kurulabilir","sev":"i"},{"cat":"VLAN","code":"show vlan brief","desc":"VLAN ozeti: ID, Name, Status (active/suspend), Ports. Hangi port hangi VLAN'da hizla gor","sev":"i"},{"cat":"VLAN","code":"show vlan id <id>","desc":"Belirli VLAN detayi: isim, durum, atanmis portlar","sev":"i"},{"cat":"VLAN","code":"show interfaces trunk","desc":"Trunk portlar: mode, encapsulation, native VLAN, allowed VLANs, active VLANs in spanning-tree. Trunk sorunu teshisi","sev":"i"},{"cat":"VLAN","code":"show interfaces <intf> switchport","desc":"Port detayi: mode (access/trunk/dynamic), VLAN, native VLAN, trunking, negotiation. Neden trunk olmuyor? kontrolu","sev":"i"},{"cat":"VLAN","code":"show mac address-table","desc":"MAC tablosu: VLAN, MAC, Type (STATIC/DYNAMIC), Ports. Cihaz hangi porta bagli? Trafik analizi","sev":"i"},{"cat":"VLAN","code":"show mac address-table address <mac>","desc":"Belirli MAC adresinin hangi portta oldugunu bul. Cihaz arama icin en cok kullanilan komut","sev":"i"},{"cat":"VLAN","code":"vlan <id>","desc":"VLAN olustur veya var olan VLAN'a gir. ID: 1-4094 (1, 1002-1005 reserved). Config modundan calisir","sev":"i"},{"cat":"VLAN","code":"name <vlan-name>","desc":"VLAN'a isim ver. Anlamli isimler kullanin: VLAN100_SUNUCULAR, VLAN200_KULLANICILAR","sev":"i"},{"cat":"VLAN","code":"switchport mode access","desc":"Portu access mode yap. Tek VLAN tasir. Bilgisayar/sunucu baglantisi icin","sev":"i"},{"cat":"VLAN","code":"switchport access vlan <id>","desc":"Access portu belirli VLAN'a ata. Belirtilmezse VLAN 1 (default) kullanilir","sev":"i"},{"cat":"VLAN","code":"switchport voice vlan <id>","desc":"IP telefon icin voice VLAN ata. Telefon voice VLAN'da, PC data VLAN'da calisir. QoS icin CoS trust gerekir","sev":"i"},{"cat":"VLAN","code":"switchport mode trunk","desc":"Portu trunk mode yap. Birden fazla VLAN tasir (802.1Q tag). Switch-switch ve switch-router arasi","sev":"i"},{"cat":"VLAN","code":"switchport trunk native vlan <id>","desc":"Native VLAN (tag'siz trafik). Iki tarafta AYNI olmali! Mismatch = STP, CDP sorunlari. Default VLAN 1, degistirmek best practice","sev":"i"},{"cat":"VLAN","code":"switchport trunk allowed vlan <list>","desc":"Trunk'ta izin verilen VLAN'lar. TUM listeyi DEGISTIRIR! Ekleme icin 'add' kullanin","sev":"w"},{"cat":"VLAN","code":"switchport trunk allowed vlan add <id>","desc":"Trunk'a VLAN ekle. Mevcut listeye EKLER (uzerine yazmaz). Yeni VLAN eklerken bunu kullanin","sev":"i"},{"cat":"VLAN","code":"switchport trunk allowed vlan remove <id>","desc":"Trunk'tan VLAN cikar. O VLAN trafigi artik trunk'tan gecmez","sev":"i"},{"cat":"VLAN","code":"switchport nonegotiate","desc":"DTP negotiation'i kapat. Guvenlik best practice — trunk'i statik ayarlayin, DTP kullanmayin","sev":"i"},{"cat":"VLAN","code":"show vtp status","desc":"VTP durumu: mode (server/client/transparent/off), domain, revision, version. VTP sorunu teshisi","sev":"i"},{"cat":"VLAN","code":"vtp mode transparent","desc":"VTP transparent: VLAN'lari lokal yonet, VTP mesajlarini ilet ama uyma. En guvenli mod","sev":"i"},{"cat":"STP","code":"show spanning-tree","desc":"Tam STP bilgisi: Root ID, Bridge ID, port rolleri (Root/Desg/Altn/Back) ve state'leri (FWD/BLK/LRN), cost, priority","sev":"i"},{"cat":"STP","code":"show spanning-tree summary","desc":"STP ozeti: mode (PVST/Rapid-PVST/MST), root bridge mi, portfast/bpduguard global durumu, VLAN bazli STP","sev":"i"},{"cat":"STP","code":"show spanning-tree vlan <id>","desc":"Belirli VLAN icin STP: root bridge kim, port rolleri, cost'lar. VLAN bazli sorun teshisi","sev":"i"},{"cat":"STP","code":"show spanning-tree root","desc":"Her VLAN icin root bridge bilgisi: root ID, cost, port. Bu switch root mu degil mi?","sev":"i"},{"cat":"STP","code":"show spanning-tree blockedports","desc":"Block durumundaki portlar. Loop onleme icin STP tarafindan kapatilmis portlar","sev":"w"},{"cat":"STP","code":"spanning-tree mode rapid-pvst","desc":"Rapid PVST+ (802.1w) mode. Sub-second convergence. PVST'den cok daha hizli. Onerilen mod","sev":"i"},{"cat":"STP","code":"spanning-tree vlan <id> root primary","desc":"Bu switch'i root bridge yap. Priority 24576 veya mevcut root'tan 4096 dusuk ayarlar","sev":"i"},{"cat":"STP","code":"spanning-tree vlan <id> root secondary","desc":"Yedek root bridge. Priority 28672 ayarlar. Primary duserse bu switch root olur","sev":"i"},{"cat":"STP","code":"spanning-tree vlan <id> priority <value>","desc":"STP priority'yi manuel ayarla. 0-61440 arasi, 4096'nin katlari. Dusuk = root olmaya yakin","sev":"i"},{"cat":"STP","code":"spanning-tree portfast","desc":"Interface'de PortFast: Listening/Learning atlanir, dogrudan Forwarding'e gecer. SADECE access portlarda! Trunk'ta LOOP riski!","sev":"i"},{"cat":"STP","code":"spanning-tree portfast default","desc":"Global PortFast: tum access portlarda otomatik PortFast. Trunk portlar etkilenmez","sev":"i"},{"cat":"STP","code":"spanning-tree bpduguard enable","desc":"BPDU Guard: BPDU alirsa portu err-disable yapar. PortFast portlarda MUTLAKA kullanin. Switch takilmasini engeller","sev":"i"},{"cat":"STP","code":"spanning-tree portfast bpduguard default","desc":"Global BPDU Guard: tum PortFast portlarda otomatik. Best practice","sev":"i"},{"cat":"STP","code":"spanning-tree guard root","desc":"Root Guard: bu porttan gelen superior BPDU'lari engelle. Root bridge degisikligini onle. Distribution layer'da kullanin","sev":"i"},{"cat":"STP","code":"spanning-tree guard loop","desc":"Loop Guard: BPDU almasi gereken ama almayan portlari Loop Inconsistent yapar. Tek yonlu link korunmasi","sev":"i"},{"cat":"STP","code":"errdisable recovery cause bpduguard","desc":"BPDU Guard'dan err-disable olan portlari otomatik recover et. Interval ile bekleme suresi ayarlanir","sev":"i"},{"cat":"STP","code":"errdisable recovery interval <seconds>","desc":"Err-disable recovery bekleme suresi. Default 300 saniye (5dk). Kisa tutarsaniz sorun devam ediyorsa tekrar kapatir","sev":"i"},{"cat":"STP","code":"debug spanning-tree events","desc":"STP olay debug: topology change, root bridge degisimi, port state degisimleri. Ornek: 'STP: VLAN0010 new root port Gi0/1, cost 4'. En guvenlisi STP debug","sev":"w"},{"cat":"STP","code":"debug spanning-tree all","desc":"Tum STP debug: BPDU'lar, state degisimleri, topology change. DIKKAT: cok fazla cikti uretir, sadece lab'da kullanin!","sev":"e"},{"cat":"STP","code":"debug spanning-tree bpdu","desc":"BPDU paket debug: gonderilen/alinan BPDU'lar, root ID, bridge ID, port ID, message age, cost degerleri. BPDU alinmiyor mu kontrolu","sev":"w"},{"cat":"STP","code":"show spanning-tree detail","desc":"Detayli STP bilgisi: port role, state, cost, priority, designated root/bridge, forward/max-age/hello timer, topology change count ve son TC zamani","sev":"i"},{"cat":"STP","code":"show spanning-tree inconsistentports","desc":"STP inconsistent portlar: PVID mismatch, type mismatch. Inconsistent port BLOCK edilir. 'show spanning-tree' de gorunmeyebilir","sev":"w"},{"cat":"STP","code":"show spanning-tree interface <intf> detail","desc":"Belirli interface STP detayi: BPDU sent/received sayilari, port state transition count, cost, guard status","sev":"i"},{"cat":"STP","code":"show errdisable recovery","desc":"Err-disable recovery durumu: hangi sebepler icin recovery aktif, interval suresi, etkilenen portlar. Ornek sebepler: bpduguard, psecure-violation, udld, storm-control, arp-inspection, dhcp-rate-limit, link-flap","sev":"i"},{"cat":"STP","code":"show errdisable detect","desc":"Err-disable detection durumu: hangi sebepler algılaniyor ve mode (port/vlan). Tum err-disable mekanizmalarini listeler","sev":"i"},{"cat":"STP","code":"errdisable recovery cause all","desc":"TUM err-disable sebepleri icin otomatik recovery etkinlestir. Dikkat: sorunun kokenini cozmeden recovery sorun tekrarlar","sev":"w"},{"cat":"STP","code":"errdisable recovery cause udld","desc":"UDLD kaynakli err-disable icin otomatik recovery. UDLD aggressive mode'da unidirectional link algilanirsa port err-disable olur","sev":"i"},{"cat":"STP","code":"errdisable recovery cause psecure-violation","desc":"Port-security violation kaynakli err-disable icin otomatik recovery","sev":"i"},{"cat":"STP","code":"errdisable recovery cause storm-control","desc":"Storm-control kaynakli err-disable icin otomatik recovery. Broadcast/multicast storm durumunda","sev":"i"},{"cat":"STP","code":"errdisable recovery cause dhcp-rate-limit","desc":"DHCP snooping rate-limit kaynakli err-disable icin otomatik recovery","sev":"i"},{"cat":"STP","code":"errdisable recovery cause arp-inspection","desc":"Dynamic ARP Inspection kaynakli err-disable icin otomatik recovery","sev":"i"},{"cat":"STP","code":"errdisable recovery cause link-flap","desc":"Link-flap kaynakli err-disable icin otomatik recovery. Port surekli up/down olursa tetiklenir","sev":"i"},{"cat":"STP","code":"udld enable","desc":"UDLD normal mode: fiber portlarda unidirectional link tespiti. Tespit edilirse port UNDETERMINED olur ama BLOCK etmez","sev":"i"},{"cat":"STP","code":"udld aggressive","desc":"UDLD aggressive mode: unidirectional link tespit edilirse port err-disable'a duser. Switch-switch fiber linklerinde onerilen","sev":"i"},{"cat":"STP","code":"udld port aggressive","desc":"Interface seviyesinde UDLD aggressive mode etkinlestir. Global UDLD'den bagimsiz, interface bazli kontrol","sev":"i"},{"cat":"STP","code":"show udld <interface>","desc":"UDLD durumu: Bidirectional/Undetermined/Disabled, neighbor bilgisi, message interval, detection time. Tek yonlu link teshisi","sev":"i"},{"cat":"STP","code":"show udld neighbors","desc":"UDLD neighbor tablosu: tum UDLD komsuluk bilgileri. Bidirectional = saglıklı, Undetermined = sorunlu","sev":"i"},{"cat":"STP","code":"udld reset","desc":"UDLD tarafindan err-disable edilen portlari sifirla. Alternatif: shutdown / no shutdown","sev":"w"},{"cat":"STP","code":"spanning-tree bpdufilter enable","desc":"BPDU Filter: BPDU gonderme ve alma. TEHLIKELI — loop korunmasi KALKAR! Sadece ozel senaryolarda. Interface seviyesi","sev":"e"},{"cat":"HSRP","code":"show standby","desc":"HSRP durumu: state (Active/Standby/Init), virtual IP, virtual MAC, priority, preempt, hello/hold timer, active/standby router IP","sev":"i"},{"cat":"HSRP","code":"show standby brief","desc":"HSRP ozet: Interface, Grp, Priority, P(reempt), State, Active addr, Standby addr, Virtual IP. Hizli kontrol","sev":"i"},{"cat":"HSRP","code":"standby <group> ip <virtual-ip>","desc":"HSRP grubu etkinlestir ve virtual IP ata. Client'lar bu IP'yi gateway olarak kullanir. Iki router'da DA ayni VIP","sev":"i"},{"cat":"HSRP","code":"standby <group> priority <1-255>","desc":"HSRP priority. Default 100. Yuksek = Active olma sansi yuksek. preempt olmadan yuksek priority bile bekler","sev":"i"},{"cat":"HSRP","code":"standby <group> preempt","desc":"Preemption: yuksek priority'li router Active rolu ALIR. Bu olmadan mevcut Active devam eder. Genellikle etkinlestirilir","sev":"i"},{"cat":"HSRP","code":"standby <group> track <interface> [decrement]","desc":"Interface izle: down olursa priority dusur. Default decrement 10. Failover tetiklemek icin","sev":"i"},{"cat":"HSRP","code":"standby <group> timers <hello> <hold>","desc":"HSRP timer. Default 3/10 saniye. Hizli failover: timers msec 100 msec 300. msec ile milisaniye","sev":"i"},{"cat":"HSRP","code":"standby <group> authentication md5 key-string <key>","desc":"HSRP MD5 authentication. Yetkisiz router'in HSRP'ye katilmasini engeller. Iki tarafta AYNI key","sev":"i"},{"cat":"HSRP","code":"standby version 2","desc":"HSRPv2: group 0-4095, IPv6 destegi. HSRPv1: group 0-255 sadece. v2 onerilen","sev":"i"},{"cat":"HSRP","code":"show vrrp","desc":"VRRP durumu: Master/Backup, priority, virtual IP. VRRP = IEEE standart (HSRP = Cisco proprietary)","sev":"i"},{"cat":"HSRP","code":"vrrp <group> ip <virtual-ip>","desc":"VRRP grubu etkinlestir. HSRP'den farki: preempt default ACIK, priority 255=IP owner","sev":"i"},{"cat":"HSRP","code":"vrrp <group> priority <1-254>","desc":"VRRP priority. Default 100. 255 = IP owner (virtual IP = gercek IP). Yuksek = Master","sev":"i"},{"cat":"HSRP","code":"debug standby","desc":"HSRP genel debug: hello paketleri, state degisimleri, election, resign mesajlari. Ornek: 'HSRP: Vl10 Grp 1 Hello in 192.168.10.2 Standby pri 100 vIP 192.168.10.254'. Split-brain teshisi icin kritik","sev":"w"},{"cat":"HSRP","code":"debug standby terse","desc":"HSRP ozet debug: sadece state degisimleri ve hatalar. Detayli hello bilgisi olmadan. Production'da daha guvenli","sev":"w"},{"cat":"HSRP","code":"debug standby errors","desc":"HSRP hata debug: authentication mismatch, group mismatch, duplicate IP. Ornek: 'HSRP: Vl10 Grp 1 Auth failure, rcvd type 2 from 192.168.10.2'","sev":"w"},{"cat":"HSRP","code":"debug standby events","desc":"HSRP olay debug: state transitions (Init->Listen->Speak->Standby->Active), track degisimleri. Ornek: 'HSRP: Vl10 Grp 1 Standby -> Active'","sev":"w"},{"cat":"HSRP","code":"debug standby packets","desc":"HSRP paket debug: gelen/giden hello paketleri detayi. Hello timer, hold timer, priority, group, virtual IP bilgileri","sev":"w"},{"cat":"HSRP","code":"show standby delay","desc":"HSRP initialization delay: interface UP olduktan sonra HSRP'nin baslamasini geciktirme. Routing convergence beklemek icin","sev":"i"},{"cat":"HSRP","code":"standby <group> preempt delay minimum <secs>","desc":"Preemption delay: Active rolu hemen alma, X saniye bekle. Routing tablolari convergence olsun diye. Ornek: delay minimum 30","sev":"i"},{"cat":"HSRP","code":"standby <group> track <obj> decrement <val>","desc":"Track ile priority decrement: track DOWN olursa priority <val> kadar duser. Decrement > (active_priority - standby_priority) olmali failover icin!","sev":"i"},{"cat":"HSRP","code":"standby delay minimum <secs> reload <secs>","desc":"HSRP baslatma gecikmesi: minimum = interface UP sonrasi, reload = cihaz reload sonrasi. Erken Active olmayi onler","sev":"i"},{"cat":"ACL","code":"show access-lists","desc":"TUM ACL'leri goster: standard, extended, named. Hit count (esleme sayisi) gorulur. 0 hit = kural hic eslesmemis","sev":"i"},{"cat":"ACL","code":"show ip access-lists","desc":"Sadece IPv4 ACL'leri goster","sev":"i"},{"cat":"ACL","code":"show ip interface <intf>","desc":"Interface'e atanmis ACL'leri goster: inbound/outbound ACL isimleri","sev":"i"},{"cat":"ACL","code":"access-list <100-199> permit tcp <src> <wc> <dst> <wc> eq <port>","desc":"Extended ACL: protokol+kaynak+hedef+port bazli. permit/deny tcp/udp/ip/icmp. eq=esit, gt=buyuk, lt=kucuk, range=aralik","sev":"i"},{"cat":"ACL","code":"access-list <100-199> deny ip any any log","desc":"Her seyi engelle ve logla. Implicit deny zaten var ama log icin explicit deny gerekir. Troubleshooting icin","sev":"i"},{"cat":"ACL","code":"ip access-list extended <name>","desc":"Named extended ACL olustur. Numara yerine isim — okunabilirlik ve yonetim kolayligi. Sequence number ile siralama","sev":"i"},{"cat":"ACL","code":"<seq#> permit/deny ...","desc":"Named ACL icinde sequence number ile kural ekle. Ornek: 15 permit tcp any host 10.1.1.1 eq 443. Araya kural ekleme","sev":"i"},{"cat":"ACL","code":"ip access-group <name> in","desc":"ACL'yi interface'e uygula. in=gelen trafik, out=giden trafik. Tek ACL / yOn / interface kurali","sev":"i"},{"cat":"ACL","code":"access-class <name> in","desc":"VTY line'a ACL uygula. SSH/Telnet erisim kontrolu. Sadece belirli IP'lerden yonetim erisimi izni","sev":"i"},{"cat":"ACL","code":"ip access-list resequence <name> <start> <increment>","desc":"ACL satirlarini yeniden numaralandir. Ornek: resequence MY_ACL 10 10. Araya kural eklemek icin bosluk olusturur","sev":"i"},{"cat":"Route-Map","code":"route-map <name> permit <seq>","desc":"Route-map entry (permit). seq = sira numarasi. permit = eslesirse isleme al. deny = eslesirse atla/engelle","sev":"i"},{"cat":"Route-Map","code":"match ip address <acl>","desc":"Route-map match kosulu: ACL ile route/trafik esle. prefix-list de kullanilabilir","sev":"i"},{"cat":"Route-Map","code":"match ip address prefix-list <name>","desc":"Prefix-list ile route esle. ACL'den daha esnek: ge/le ile prefix uzunlugu filtreleme","sev":"i"},{"cat":"Route-Map","code":"match as-path <as-path-acl>","desc":"BGP AS-path ile esle. BGP route filtreleme icin. ip as-path access-list ile birlikte","sev":"i"},{"cat":"Route-Map","code":"set local-preference <value>","desc":"BGP local-preference ayarla. Yuksek = tercih edilen. iBGP icinde route tercihi icin","sev":"i"},{"cat":"Route-Map","code":"set as-path prepend <as-numbers>","desc":"AS-path'e AS ekle. Route'u daha az tercih edilen yap. Outbound'da uygulanir. Ornek: prepend 65000 65000","sev":"i"},{"cat":"Route-Map","code":"set metric <value>","desc":"Metric/MED ayarla. BGP'de MED, OSPF'te cost, EIGRP'de metric olarak kullanilir","sev":"i"},{"cat":"Route-Map","code":"set ip next-hop <ip>","desc":"PBR: next-hop degistir. Belirli trafigin farkli gateway'den cikmasi icin. Interface'e ip policy route-map ile uygulanir","sev":"i"},{"cat":"Route-Map","code":"set community <value> additive","desc":"BGP community ata. additive = mevcut community'leri koru ve yenisini ekle. no-export, no-advertise, local-AS","sev":"i"},{"cat":"Route-Map","code":"ip prefix-list <name> seq <#> permit <prefix/len> le <max>","desc":"Prefix-list: prefix ve uzunluk filtrele. le = max uzunluk, ge = min uzunluk. Ornek: 10.0.0.0/8 le 24 = /8 ile /24 arasi","sev":"i"},{"cat":"Route-Map","code":"ip policy route-map <name>","desc":"PBR'i interface'e uygula (inbound). Bu interface'den gelen trafik route-map'e gore yonlendirilir","sev":"i"},{"cat":"Route-Map","code":"show route-map","desc":"Tum route-map'leri goster: match/set komutlari, policy routing counts. Match sayisi 0 = hic eslesmemis","sev":"i"},{"cat":"Route-Map","code":"show ip policy","desc":"PBR uygulanan interface'leri goster. Hangi interface'de hangi route-map aktif?","sev":"i"},{"cat":"Interface","code":"show ip interface brief","desc":"Tum interface ozeti: Interface, IP-Address, OK?, Method, Status (up/admin down), Protocol (up/down). En cok kullanilan komut","sev":"i"},{"cat":"Interface","code":"show interfaces","desc":"Detayli interface bilgisi: status, speed, duplex, MTU, BW, errors (CRC/input/output/collision), counters","sev":"i"},{"cat":"Interface","code":"show interfaces <intf>","desc":"Belirli interface detayi. input errors/CRC > 0 ise kablo/port sorunu. collisions > 0 ise duplex mismatch","sev":"i"},{"cat":"Interface","code":"show interfaces status","desc":"Port ozeti: Port, Name, Status (connected/notconnect/err-disabled), VLAN, Duplex, Speed, Type. L2 switch icin","sev":"i"},{"cat":"Interface","code":"show interfaces counters errors","desc":"Interface hata sayaclari: Align-Err, FCS-Err, Xmit-Err, Rcv-Err, UnderSize, OutDiscards. Sifirdan buyuk = SORUN","sev":"i"},{"cat":"Interface","code":"show ip route","desc":"Tam routing tablosu: C=Connected, S=Static, D=EIGRP, O=OSPF, B=BGP, R=RIP. [AD/Metric] via next-hop","sev":"i"},{"cat":"Interface","code":"show ip route <prefix>","desc":"Belirli prefix icin route detayi: kaynak protokol, metric, last update, next-hop","sev":"i"},{"cat":"Interface","code":"show ip arp","desc":"ARP tablosu: Protocol, Address, Age, Hardware Addr, Type, Interface. Age (dk) yuksekse eski kayit","sev":"i"},{"cat":"Interface","code":"show version","desc":"IOS versiyonu, uptime, hardware model, RAM, flash, config-register. Cihaz envanter ve durum bilgisi","sev":"i"},{"cat":"Interface","code":"show inventory","desc":"Hardware envanteri: NAME, DESCR, PID (Product ID), VID, SN (Serial Number). RMA ve lisanslama icin","sev":"i"},{"cat":"Interface","code":"interface <type> <number>","desc":"Interface config moduna gir. Ornekler: GigabitEthernet0/0, FastEthernet0/1, Serial0/0/0, Loopback0, Vlan100","sev":"i"},{"cat":"Interface","code":"interface range <type> <range>","desc":"Birden fazla interface'i ayni anda konfigure et. Ornekler: range g0/1-4, range f0/1-12, range g0/1-2, g0/5-6","sev":"i"},{"cat":"Interface","code":"ip address <ip> <mask>","desc":"Interface'e IP adresi ata. secondary parametresi ile ikinci IP eklenebilir","sev":"i"},{"cat":"Interface","code":"no shutdown","desc":"Interface'i etkinlestir (UP). Default olarak router interface'leri shutdown, switch portlari no shutdown","sev":"ok"},{"cat":"Interface","code":"shutdown","desc":"Interface'i administratif olarak kapat (admin down). Trafik KESILIR. Bakim veya sorun izolasyonu icin","sev":"e"},{"cat":"Interface","code":"description <text>","desc":"Interface aciklamasi ekle. Ornek: description UPLINK_TO_ISP1. Dokumantasyon best practice","sev":"i"},{"cat":"Interface","code":"speed auto","desc":"Port hizini auto-negotiate yap. 10/100/1000 manuel de ayarlanabilir. Karsi taraf ile eslesmeli","sev":"i"},{"cat":"Interface","code":"duplex auto","desc":"Duplex modunu auto-negotiate yap. full/half manuel ayarlanabilir. Mismatch = CRC/collision hatalari","sev":"i"},{"cat":"Interface","code":"mtu <bytes>","desc":"MTU ayarla. Default 1500. Jumbo frame icin 9000-9216. Tum yol boyunca AYNI olmali!","sev":"i"},{"cat":"Interface","code":"no switchport","desc":"L2 portu L3 routed porta cevir. IP adresi atanabilir hale gelir. L3 switch'lerde uplink/routing icin","sev":"i"},{"cat":"Interface","code":"interface loopback <number>","desc":"Loopback interface olustur. Her zaman UP. Router ID, management IP, BGP source icin ideal","sev":"i"},{"cat":"Interface","code":"interface vlan <id>","desc":"SVI (Switch Virtual Interface) olustur. L3 switch'te VLAN icin gateway IP. ip routing etkin olmali","sev":"i"},{"cat":"Interface","code":"ip routing","desc":"L3 switch'te IP routing etkinlestir. SVI'lar arasi routing icin ZORUNLU. Olmadan L3 calismaz","sev":"i"},{"cat":"Interface","code":"show cdp neighbors","desc":"CDP komsu listesi: Device ID, Local Intf, Holdtme, Capability, Platform, Port ID. Topoloji kesfetme","sev":"i"},{"cat":"Interface","code":"show cdp neighbors detail","desc":"CDP detayli komsu bilgisi: management IP, platform, IOS version, native VLAN, duplex. Uzak cihaz bilgisi","sev":"i"},{"cat":"Interface","code":"show lldp neighbors","desc":"LLDP (IEEE) komsu listesi. CDP'nin multi-vendor versiyonu. Cisco + non-Cisco cihazlar","sev":"i"},{"cat":"Interface","code":"show ip interface","desc":"Interface IP detayi: ACL uygulanmis mi, proxy-arp, directed-broadcast, NAT inside/outside, MTU","sev":"i"},{"cat":"Port Security","code":"switchport port-security","desc":"Port-security etkinlestir. Sadece access mode portlarda calisir! Trunk'ta calismaz. Yetkisiz cihaz engelleme","sev":"i"},{"cat":"Port Security","code":"switchport port-security maximum <number>","desc":"Portta izin verilen max MAC sayisi. Default 1. IP phone + PC icin 2 gerekir","sev":"i"},{"cat":"Port Security","code":"switchport port-security mac-address sticky","desc":"Dinamik ogrenmis MAC'leri sticky (running-config'e kaydet) yap. Tekrar baglandiginda otomatik izin verir","sev":"i"},{"cat":"Port Security","code":"switchport port-security mac-address <mac>","desc":"Statik MAC tanimla. Sadece bu MAC'ten trafik kabul edilir. En katı kontrol","sev":"i"},{"cat":"Port Security","code":"switchport port-security violation shutdown","desc":"Ihlal durumunda portu err-disable yap. shutdown=kapat (default), restrict=engelle+log, protect=sadece engelle","sev":"i"},{"cat":"Port Security","code":"show port-security","desc":"Port-security ozeti: SecurePort, MaxSecureAddr, CurrentAddr, SecurityViolation, SecurityAction","sev":"i"},{"cat":"Port Security","code":"show port-security interface <intf>","desc":"Belirli port icin security detayi: status (Secure-up/Secure-shutdown), violation count, son ihlal MAC","sev":"i"},{"cat":"Port Security","code":"show port-security address","desc":"Guvenli MAC listesi: VLAN, MAC, Type (Static/SecureSticky/SecureDynamic), Port. Hangi MAC nerede?","sev":"i"},{"cat":"DHCP Snooping","code":"ip dhcp snooping","desc":"Global DHCP snooping etkinlestir. Rogue DHCP server korunmasi. Ek olarak VLAN bazli da etkinlestirin","sev":"i"},{"cat":"DHCP Snooping","code":"ip dhcp snooping vlan <id>","desc":"Belirli VLAN'da DHCP snooping etkinlestir. Hem global hem VLAN bazli acilmali","sev":"i"},{"cat":"DHCP Snooping","code":"ip dhcp snooping trust","desc":"Interface'i trust yap (uplink/trunk portlari). Trust olmayan portlardan gelen DHCP server mesajlari (OFFER/ACK) ENGELLENIR","sev":"i"},{"cat":"DHCP Snooping","code":"show ip dhcp snooping","desc":"DHCP snooping durumu: etkin mi, hangi VLAN'lar, trust portlar","sev":"i"},{"cat":"DHCP Snooping","code":"show ip dhcp snooping binding","desc":"DHCP snooping binding tablosu: MAC, IP, Lease, VLAN, Interface. DAI ve IP Source Guard bu tabloyu kullanir","sev":"i"},{"cat":"IPsec VPN","code":"crypto isakmp policy <priority>","desc":"ISAKMP (IKE Phase 1) policy olustur. Priority: 1-10000 (dusuk = yuksek oncelik). Peer ile eslesen ilk policy kullanilir","sev":"i"},{"cat":"IPsec VPN","code":"encryption aes 256","desc":"ISAKMP policy icinde sifreleme algoritmasi: aes 128/192/256, 3des, des. AES-256 onerilen","sev":"i"},{"cat":"IPsec VPN","code":"hash sha256","desc":"ISAKMP policy icinde hash algoritmasi: sha, sha256, sha384, sha512, md5. SHA-256+ onerilen","sev":"i"},{"cat":"IPsec VPN","code":"authentication pre-share","desc":"ISAKMP policy icinde kimlik dogrulama yontemi: pre-share (PSK), rsa-sig (sertifika), rsa-encr","sev":"i"},{"cat":"IPsec VPN","code":"group 14","desc":"ISAKMP policy icinde Diffie-Hellman grubu: 1 (768-bit), 2 (1024-bit), 5 (1536-bit), 14 (2048-bit), 15 (3072-bit), 16 (4096-bit). group 14+ onerilen","sev":"i"},{"cat":"IPsec VPN","code":"lifetime 86400","desc":"ISAKMP policy icinde SA yasam suresi (saniye). Default 86400 (24 saat). Kisa sure = daha guvenli ama daha fazla rekey","sev":"i"},{"cat":"IPsec VPN","code":"crypto isakmp key <psk> address <peer-ip>","desc":"Pre-shared key tanimla. PSK = paylasilan sifre, peer-ip = karsi taraf IP. Wildcard icin 0.0.0.0 0.0.0.0 kullanilabilir","sev":"i"},{"cat":"IPsec VPN","code":"crypto isakmp key <psk> hostname <peer-hostname>","desc":"Hostname bazli PSK tanimla. Dinamik IP'li peer'lar icin kullanisli","sev":"i"},{"cat":"IPsec VPN","code":"crypto isakmp keepalive 10 3","desc":"DPD (Dead Peer Detection) etkinlestir: 10 saniye interval, 3 deneme. Peer down tespiti icin","sev":"i"},{"cat":"IPsec VPN","code":"crypto isakmp nat-traversal","desc":"NAT-T (NAT Traversal) etkinlestir. IPsec paketleri NAT cihazin arkasinda ise UDP 4500 encapsulation kullanilir","sev":"i"},{"cat":"IPsec VPN","code":"crypto isakmp aggressive-mode disable","desc":"Aggressive mode'u devre disi birak. Main mode daha guvenlidir — identity korunur. Guvenlik best practice","sev":"i"},{"cat":"IPsec VPN","code":"crypto ipsec transform-set <name> esp-aes 256 esp-sha256-hmac","desc":"IPsec Phase 2 transform-set olustur. Sifreleme (esp-aes, esp-3des) + HMAC (esp-sha-hmac, esp-sha256-hmac). mode tunnel default","sev":"i"},{"cat":"IPsec VPN","code":"mode tunnel","desc":"Transform-set icinde: tunnel mode (default) = tum IP paketi sifrelenir. transport mode = sadece payload sifrelenir (GRE+IPsec icin bazen kullanilir)","sev":"i"},{"cat":"IPsec VPN","code":"mode transport","desc":"Transform-set icinde transport mode. GRE over IPsec senaryolarinda GRE zaten encapsulation yaptigi icin transport mode yeterli olabilir","sev":"i"},{"cat":"IPsec VPN","code":"crypto ipsec security-association lifetime seconds 3600","desc":"IPsec SA yasam suresi (saniye). Default 3600 (1 saat). Kisa = daha guvenli, uzun = daha az rekey overhead","sev":"i"},{"cat":"IPsec VPN","code":"crypto ipsec security-association lifetime kilobytes 4608000","desc":"IPsec SA yasam suresi (kilobyte). Veri limitine ulasilinca rekey yapilir","sev":"i"},{"cat":"IPsec VPN","code":"crypto ipsec df-bit clear","desc":"IPsec paketlerinde Don't Fragment bitini temizle. MTU/fragmentation sorunlarini cozebilir","sev":"i"},{"cat":"IPsec VPN","code":"crypto ipsec fragmentation before-encryption","desc":"Sifreleme oncesi fragmentasyon yap. PMTUD sorunlarini onler. after-encryption default","sev":"i"},{"cat":"IPsec VPN","code":"crypto map <name> <seq> ipsec-isakmp","desc":"Crypto map entry olustur. seq = sira numarasi (10, 20...). ipsec-isakmp = IKE kullan. ipsec-manual = manuel key","sev":"i"},{"cat":"IPsec VPN","code":"set peer <peer-ip>","desc":"Crypto map icinde: karsi taraf VPN peer IP adresi. Birden fazla peer failover icin eklenebilir","sev":"i"},{"cat":"IPsec VPN","code":"set transform-set <ts-name>","desc":"Crypto map icinde: hangi transform-set kullanilacak","sev":"i"},{"cat":"IPsec VPN","code":"set pfs group14","desc":"Perfect Forward Secrecy etkinlestir. Her Phase 2 SA icin yeni DH key uretilir. Guvenlik icin onerilen","sev":"i"},{"cat":"IPsec VPN","code":"match address <acl-name>","desc":"Crypto map icinde: hangi trafik sifrelenir (interesting traffic). ACL ile tanimlanan trafik IPsec tunelden gider","sev":"i"},{"cat":"IPsec VPN","code":"set security-association lifetime seconds 3600","desc":"Crypto map icinde SA lifetime override. Transform-set seviyesindeki ayari ezer","sev":"i"},{"cat":"IPsec VPN","code":"interface GigabitEthernet0/0\n crypto map <name>","desc":"Crypto map'i WAN interface'ine uygula. Bu interface'den gecen interesting traffic sifrelenir","sev":"i"},{"cat":"IPsec VPN","code":"ip access-list extended VPN-TRAFFIC\n permit ip 192.168.1.0 0.0.0.255 10.64.10.0 0.0.0.255","desc":"VPN interesting traffic ACL. Bu ACL'deki trafik IPsec tunelden gider. Wildcard mask kullanilir (subnet mask degil!)","sev":"i"},{"cat":"IPsec VPN","code":"interface Tunnel0","desc":"GRE tunnel interface'i olustur/gir. Tunnel numarasi yerel (0-2147483647). Logical interface","sev":"i"},{"cat":"IPsec VPN","code":"ip address 10.0.0.1 255.255.255.252","desc":"Tunnel interface'ine IP ata. Karsi taraf ile ayni subnet olmali (/30 veya /31 onerilen)","sev":"i"},{"cat":"IPsec VPN","code":"tunnel source GigabitEthernet0/0","desc":"GRE tunnel kaynak interface veya IP. Genellikle WAN interface kullanilir","sev":"i"},{"cat":"IPsec VPN","code":"tunnel destination <peer-ip>","desc":"GRE tunnel hedef IP. Karsi tarafin WAN IP adresi","sev":"i"},{"cat":"IPsec VPN","code":"tunnel mode gre ip","desc":"Tunnel modu: gre ip (default GRE), gre multipoint (DMVPN), ipsec ipv4 (pure IPsec). Default gre ip","sev":"i"},{"cat":"IPsec VPN","code":"tunnel protection ipsec profile <profile-name>","desc":"GRE tunnel'i IPsec ile koru. Profile onceden tanimlanmis olmali. GRE over IPsec en yaygin yontem","sev":"i"},{"cat":"IPsec VPN","code":"ip mtu 1400","desc":"Tunnel interface MTU. GRE (24B) + IPsec (50-70B) overhead nedeniyle 1400 onerilen. PMTUD sorunlarini onler","sev":"i"},{"cat":"IPsec VPN","code":"ip tcp adjust-mss 1360","desc":"TCP MSS degerini ayarla. TCP SYN paketlerinde MSS'i dusurur. Fragmentation sorunlarini onler. MTU-40 hesabi","sev":"i"},{"cat":"IPsec VPN","code":"keepalive 10 3","desc":"Tunnel keepalive: 10 saniye interval, 3 deneme. Tunnel down tespiti icin. BFD ile birlikte kullanilabilir","sev":"i"},{"cat":"IPsec VPN","code":"tunnel key <number>","desc":"GRE tunnel key. Ayni kaynak/hedef ile birden fazla tunnel ayirt etmek icin. Karsi tarafla eslesmeli","sev":"i"},{"cat":"IPsec VPN","code":"crypto ipsec profile <name>","desc":"IPsec profili olustur. Tunnel protection ile kullanilir. Crypto map'e alternatif modern yontem","sev":"i"},{"cat":"IPsec VPN","code":"show crypto isakmp sa","desc":"IKE Phase 1 SA durumu. QM_IDLE = basarili, MM_NO_STATE = basarisiz. src/dst IP'leri ve durum gorulur","sev":"i"},{"cat":"IPsec VPN","code":"show crypto isakmp sa detail","desc":"IKE Phase 1 SA detayli bilgi: encryption, hash, auth, DH group, lifetime, rekey zamani","sev":"i"},{"cat":"IPsec VPN","code":"show crypto ipsec sa","desc":"IPsec Phase 2 SA durumu. Encaps/decaps paket sayilari, SPI, transform-set, ACL. Sifir paket = trafik akmiyorsa","sev":"i"},{"cat":"IPsec VPN","code":"show crypto ipsec sa peer <peer-ip>","desc":"Belirli peer icin IPsec SA detayi. Birden fazla SA varsa hepsini gosterir","sev":"i"},{"cat":"IPsec VPN","code":"show crypto ipsec sa detail","desc":"IPsec SA detayli bilgi: identity, lifetime remaining, kilobyte remaining, replay window","sev":"i"},{"cat":"IPsec VPN","code":"show crypto map","desc":"Crypto map konfigurasyonu ve durumu: peer, ACL, transform-set, interface atamalari","sev":"i"},{"cat":"IPsec VPN","code":"show crypto session","desc":"Tum crypto session'larin ozeti: peer IP, status (UP-ACTIVE/DOWN), inbound/outbound SA sayisi","sev":"i"},{"cat":"IPsec VPN","code":"show crypto session detail","desc":"Crypto session detayli: IKE SA, IPsec flow, paket sayaclari, uptime","sev":"i"},{"cat":"IPsec VPN","code":"show crypto engine connections active","desc":"Aktif crypto engine baglantilari: algorithm, encrypt/decrypt, SPI. Hardware crypto accelerator kullanimi","sev":"i"},{"cat":"IPsec VPN","code":"show crypto isakmp policy","desc":"Tanimlanmis ISAKMP policy'lerin listesi: priority, encryption, hash, auth, DH group, lifetime","sev":"i"},{"cat":"IPsec VPN","code":"clear crypto sa","desc":"Tum IPsec SA'lari temizle. Tunnel yeniden kurulur (rekey). Troubleshooting icin. TRAFIK KESILIR gecici olarak!","sev":"e"},{"cat":"IPsec VPN","code":"clear crypto sa peer <peer-ip>","desc":"Belirli peer'in IPsec SA'larini temizle. Diger peer'lar etkilenmez","sev":"w"},{"cat":"IPsec VPN","code":"clear crypto isakmp","desc":"Tum IKE Phase 1 SA'lari temizle. Phase 2 de duser. Tam VPN reset","sev":"e"},{"cat":"IPsec VPN","code":"debug crypto isakmp","desc":"IKE Phase 1 negotiation debug. PSK mismatch, policy mismatch, identity sorunlari burada gorulur. Cok verbose!","sev":"w"},{"cat":"IPsec VPN","code":"debug crypto ipsec","desc":"IPsec Phase 2 debug. Transform-set mismatch, ACL mismatch (proxy identity), PFS sorunlari gorulur","sev":"w"},{"cat":"IPsec VPN","code":"debug crypto condition peer ipv4 <peer-ip>","desc":"Debug'u belirli peer ile sinirla. Production ortaminda TUM debug yerine bu kullanilmali","sev":"i"},{"cat":"IPsec VPN","code":"debug crypto isakmp detail","desc":"IKE Phase 1 DETAYLI debug. Standart debug crypto isakmp'den daha fazla bilgi: proposal detaylari, hash/encryption karsilastirmasi, DH group negotiation adimlari","sev":"w"},{"cat":"IPsec VPN","code":"debug crypto engine","desc":"Crypto engine debug: sifreleme/desifreleme islemlerini izle. Hardware crypto accelerator sorunlarini tespit eder. Paket bazinda encrypt/decrypt loglari","sev":"w"},{"cat":"IPsec VPN","code":"debug crypto key-exchange","desc":"Diffie-Hellman key exchange debug. DH group mismatch, key uretim hatalari, MODP sorunlari gorulur","sev":"w"},{"cat":"IPsec VPN","code":"debug crypto condition connid <id> engine-id <id>","desc":"Belirli connection ID ve engine icin conditional debug. Coklu tunnel ortaminda spesifik tunnel debug etmek icin","sev":"i"},{"cat":"IPsec VPN","code":"debug crypto condition spi <spi-value>","desc":"Belirli SPI degeri icin conditional debug. Tek bir IPsec SA'yi debug etmek icin","sev":"i"},{"cat":"IPsec VPN","code":"debug crypto condition fvrf <vrf-name>","desc":"Belirli Front-door VRF icin conditional debug. VRF-aware IPsec ortamlarinda kullanilir","sev":"i"},{"cat":"IPsec VPN","code":"debug crypto condition unmatched","desc":"Hicbir condition'a uymayan debug mesajlarini da goster. Beklenmeyen peer'lardan gelen paketleri tespit etmek icin","sev":"i"},{"cat":"IPsec VPN","code":"show crypto debug-condition","desc":"Aktif crypto debug condition'larini goster: peer, connid, spi, fvrf, ivrf filtreleri. Hangi kosullarin aktif oldugunu dogrular","sev":"i"},{"cat":"IPsec VPN","code":"show crypto isakmp sa count","desc":"Toplam ISAKMP SA sayisini goster. Cok fazla SA = memory/performance sorunu olabilir","sev":"i"},{"cat":"IPsec VPN","code":"show crypto ipsec sa count","desc":"Toplam IPsec SA sayisini goster. SA limit'ine yaklasma durumunu kontrol et","sev":"i"},{"cat":"IPsec VPN","code":"clear crypto session","desc":"Tum crypto session'lari temizle (IKE + IPsec). clear crypto sa + clear crypto isakmp birlikte. En kapsamli VPN reset","sev":"e"},{"cat":"IPsec VPN","code":"clear crypto session remote <peer-ip>","desc":"Belirli peer'in tum crypto session'ini temizle. Diger peer'lar etkilenmez","sev":"w"},{"cat":"IPsec VPN","code":"show crypto ipsec transform-set","desc":"Tanimli tum transform-set'leri goster: encryption, hash, mode (tunnel/transport). Iki tarafin eslestigini dogrulamak icin","sev":"i"},{"cat":"IPsec VPN","code":"show crypto isakmp key","desc":"Tanimli pre-shared key'leri goster (maskelenmis). Hangi peer'lara PSK tanimli oldugunu dogrulamak icin","sev":"i"},{"cat":"IPsec VPN","code":"show interfaces Tunnel0","desc":"Tunnel interface detayli bilgi: line protocol up/down, MTU, bandwidth, packets in/out, errors, keepalive, tunnel source/destination, tunnel protection","sev":"i"},{"cat":"IPsec VPN","code":"show interfaces Tunnel0 | include keepalive","desc":"Tunnel keepalive ayarlarini kontrol et. Keepalive 10/3 = 10 saniye interval, 3 retry. Keepalive is not set = keepalive devre disi","sev":"i"},{"cat":"IPsec VPN","code":"show ip interface brief | include Tunnel","desc":"Tum tunnel interface'lerinin durumu: IP, Status, Protocol. up/down veya up/up olmasini kontrol et","sev":"i"},{"cat":"IPsec VPN","code":"tunnel path-mtu-discovery","desc":"GRE tunnel icin Path MTU Discovery etkinlestir. PMTUD, optimal MTU'yu otomatik kesfeder. Fragmentation sorunlarini azaltir","sev":"i"},{"cat":"IPsec VPN","code":"crypto ipsec fragmentation after-encryption","desc":"IPsec sifreleme SONRASI fragmentasyon (default). Buyuk paketler sifrelendikten sonra parcalanir. CPU yogun olabilir","sev":"i"},{"cat":"IPsec VPN","code":"crypto isakmp nat-traversal 20","desc":"NAT-T keepalive interval (saniye). Default 20. NAT cihazin UDP 4500 session'ini canli tutar. NAT timeout'undan kisa olmali","sev":"i"},{"cat":"IPsec VPN","code":"show crypto ipsec sa peer <peer-ip> detail","desc":"Belirli peer icin detayli SA bilgisi: SPI, remaining lifetime (seconds/kilobytes), replay window size, pkts encaps/decaps/encrypt/decrypt, send/recv errors","sev":"i"},{"cat":"IPsec VPN","code":"ip route <tunnel-dest> 255.255.255.255 <next-hop>","desc":"GRE tunnel destination icin static route. Recursive routing sorununu onler. Tunnel destination'a tunnel uzerinden degil physical interface uzerinden ulasilmasini saglar","sev":"i"},{"cat":"MPLS","code":"mpls ip","desc":"Interface uzerinde MPLS'i etkinlestir. Global config'de veya interface altinda kullanilir. LDP komsu olusumu baslar","sev":"i"},{"cat":"MPLS","code":"mpls ldp router-id Loopback0 force","desc":"LDP router-id olarak Loopback0 kullan. force = mevcut session'lari yeniden baslatir. Best practice: her zaman Loopback kullanin","sev":"i"},{"cat":"MPLS","code":"mpls label protocol ldp","desc":"Label dagitim protokolu: ldp (default), tdp (eski Cisco), bgp. LDP standarttir","sev":"i"},{"cat":"MPLS","code":"mpls label range <min> <max>","desc":"Label araligi tanimla. Default: 16-1048575. Ozel label politikasi icin","sev":"i"},{"cat":"MPLS","code":"mpls ldp discovery transport-address interface","desc":"LDP transport adresi olarak interface IP kullan. Default Loopback tercih edilir","sev":"i"},{"cat":"MPLS","code":"mpls ldp neighbor <ip> password <key>","desc":"LDP komsusu icin MD5 authentication. Guvenlik icin onerilen","sev":"i"},{"cat":"MPLS","code":"mpls mtu <bytes>","desc":"MPLS MTU degerini ayarla. MPLS label (4 byte) eklendigi icin physical MTU'dan buyuk olmali. 1508+ onerilen","sev":"i"},{"cat":"MPLS","code":"show mpls ldp neighbor","desc":"LDP komsu listesi: peer IP, state (Oper = aktif), uptime, session handle. Komsuluk dogrulamasi","sev":"i"},{"cat":"MPLS","code":"show mpls ldp neighbor detail","desc":"LDP komsu detay: TCP connection, keepalive interval, label space, address bound","sev":"i"},{"cat":"MPLS","code":"show mpls forwarding-table","desc":"LFIB (Label Forwarding Information Base): local label, outgoing label, prefix, next-hop. MPLS paket yonlendirme tablosu","sev":"i"},{"cat":"MPLS","code":"show mpls forwarding-table <prefix>","desc":"Belirli prefix icin LFIB entry. Label swap/push/pop islemi gorulur","sev":"i"},{"cat":"MPLS","code":"show mpls ldp bindings","desc":"LIB (Label Information Base): local/remote label binding'leri. Her prefix icin hangi label atanmis","sev":"i"},{"cat":"MPLS","code":"show mpls ldp bindings <prefix> <mask>","desc":"Belirli prefix icin label binding detayi. Local ve remote (peer'lardan gelen) label'lar gorulur","sev":"i"},{"cat":"MPLS","code":"show mpls ldp discovery","desc":"LDP discovery sureci: hangi interface'lerde LDP aktif, hello interval, hold time, komsular","sev":"i"},{"cat":"MPLS","code":"show mpls interfaces","desc":"MPLS aktif interface listesi: interface adi, IP, operational status, LDP/RSVP","sev":"i"},{"cat":"MPLS","code":"show mpls ip binding","desc":"MPLS IP label binding'leri: FEC (prefix), local label, remote label/peer","sev":"i"},{"cat":"MPLS","code":"show mpls ldp parameters","desc":"LDP parametre ozeti: protocol version, router-id, session hold time, keepalive interval, discovery transport","sev":"i"},{"cat":"MPLS","code":"traceroute mpls ipv4 <prefix> <mask>","desc":"MPLS LSP (Label Switched Path) boyunca traceroute. Her hop'ta label bilgisi gorulur. LSP dogrulamasi","sev":"i"},{"cat":"MPLS","code":"ping mpls ipv4 <prefix> <mask>","desc":"MPLS LSP uzerinden ping. End-to-end MPLS data plane dogrulamasi","sev":"i"},{"cat":"MPLS","code":"ip vrf <name>","desc":"VRF olustur (IOS Classic syntax). VRF = Virtual Routing and Forwarding. Multi-tenant routing izolasyonu","sev":"i"},{"cat":"MPLS","code":"vrf definition <name>","desc":"VRF olustur (Modern IOS / IOS-XE syntax). address-family ipv4/ipv6 destekler","sev":"i"},{"cat":"MPLS","code":"rd <ASN:nn>","desc":"Route Distinguisher: VRF icin benzersiz tanimlayici. Format: ASN:nn veya IP:nn. Ayni prefix'leri farkli VRF'lerde ayirt eder","sev":"i"},{"cat":"MPLS","code":"route-target export <ASN:nn>","desc":"Route Target export: bu VRF'in route'larini hangi RT ile etiketleyecek. MP-BGP ile dagitilir","sev":"i"},{"cat":"MPLS","code":"route-target import <ASN:nn>","desc":"Route Target import: hangi RT etiketli route'lari bu VRF'e alacak. Export/Import eslesmesi gerekli","sev":"i"},{"cat":"MPLS","code":"route-target both <ASN:nn>","desc":"Ayni RT degeri icin hem import hem export. Basit hub-spoke veya full-mesh icin","sev":"i"},{"cat":"MPLS","code":"interface GigabitEthernet0/1\n ip vrf forwarding <vrf-name>","desc":"Interface'i VRF'e ata. DIKKAT: IP adresi silinir, tekrar atanmali! Mevcut trafik KESILIR","sev":"w"},{"cat":"MPLS","code":"show ip vrf","desc":"Tum VRF'lerin listesi: VRF adi, RD, interface atamalari","sev":"i"},{"cat":"MPLS","code":"show ip vrf detail","desc":"VRF detayli bilgi: RD, RT import/export, interface'ler, route sayisi, VRF ID","sev":"i"},{"cat":"MPLS","code":"show ip route vrf <name>","desc":"VRF routing tablosu. Global routing tablosundan bagimsiz, izole route'lar gorulur","sev":"i"},{"cat":"MPLS","code":"show ip bgp vpnv4 all","desc":"Tum VPNv4 route'lari. RD, RT, label, next-hop bilgileri. MPLS L3VPN route dogrulamasi","sev":"i"},{"cat":"MPLS","code":"show ip bgp vpnv4 vrf <name>","desc":"Belirli VRF icin VPNv4 BGP route'lari. Prefix, next-hop, label, AS-path gorulur","sev":"i"},{"cat":"MPLS","code":"ping vrf <name> <destination>","desc":"VRF icinden ping. Global routing table'dan degil, belirtilen VRF'in tablosundan gider","sev":"i"},{"cat":"QoS","code":"class-map match-any <name>","desc":"Class-map olustur: trafik siniflandirmasi. match-any = herhangi biri eslesirse (OR). match-all = hepsi eslesmeli (AND)","sev":"i"},{"cat":"QoS","code":"class-map match-all <name>","desc":"Class-map olustur: match-all = tum match kriterleri eslesmeli (AND logic). Daha kisitlayici","sev":"i"},{"cat":"QoS","code":"match dscp ef","desc":"Class-map icinde: DSCP degerine gore esle. ef=Expedited Forwarding (46), af11-af43, cs1-cs7, default (0)","sev":"i"},{"cat":"QoS","code":"match dscp af31 af32 af33","desc":"Class-map icinde: birden fazla DSCP degeri. AF3x = assured forwarding class 3. Toplu eslestirme","sev":"i"},{"cat":"QoS","code":"match ip dscp <0-63>","desc":"Class-map icinde: numerik DSCP degeri ile esle (0-63)","sev":"i"},{"cat":"QoS","code":"match cos <0-7>","desc":"Class-map icinde: 802.1Q CoS degerine gore esle. 0=best-effort, 5=voice, 6-7=network control","sev":"i"},{"cat":"QoS","code":"match access-group name <acl-name>","desc":"Class-map icinde: ACL ile esle. IP adresi/port bazli trafik siniflandirma. Detayli filtre icin","sev":"i"},{"cat":"QoS","code":"match access-group <acl-number>","desc":"Class-map icinde: numarali ACL ile esle. 100-199 veya 2000-2699 extended ACL","sev":"i"},{"cat":"QoS","code":"match protocol <protocol>","desc":"Class-map icinde: NBAR protokol eslesmesi. http, ssh, dns, citrix, rtp, sip vb. L7 siniflandirma","sev":"i"},{"cat":"QoS","code":"match ip precedence <0-7>","desc":"Class-map icinde: IP Precedence degeri. 0=routine, 5=critical, 6=internetwork, 7=network","sev":"i"},{"cat":"QoS","code":"match vlan <vlan-id>","desc":"Class-map icinde: VLAN ID'ye gore esle. Belirli VLAN'daki trafik icin QoS politikasi","sev":"i"},{"cat":"QoS","code":"match input-interface <interface>","desc":"Class-map icinde: giris interface'ine gore esle. Interface bazli trafik yonetimi","sev":"i"},{"cat":"QoS","code":"policy-map <name>","desc":"Policy-map olustur: QoS politikasi. Class-map'ler ile siniflandirilan trafige aksiyon uygular","sev":"i"},{"cat":"QoS","code":"class <class-map-name>","desc":"Policy-map icinde class-map referans et. Her class icin farkli aksiyon tanimlanir","sev":"i"},{"cat":"QoS","code":"class class-default","desc":"Policy-map icinde default class. Hicbir class-map ile eslesmeyen trafik buraya duser","sev":"i"},{"cat":"QoS","code":"set dscp ef","desc":"Policy-map class icinde: DSCP degerini ayarla (mark). ef=46, af11=10, af21=18, cs3=24, default=0. Trafik isaretleme","sev":"i"},{"cat":"QoS","code":"set cos <0-7>","desc":"Policy-map class icinde: CoS degerini ayarla. L2 seviyesinde oncelik isaretleme","sev":"i"},{"cat":"QoS","code":"set ip precedence <0-7>","desc":"Policy-map class icinde: IP Precedence degerini ayarla. Eski ToS bazli isaretleme","sev":"i"},{"cat":"QoS","code":"set ip dscp <value>","desc":"Policy-map class icinde: IP DSCP degerini ayarla. Numerik (0-63) veya isimli (ef, af31, cs5)","sev":"i"},{"cat":"QoS","code":"bandwidth <kbps>","desc":"Policy-map class icinde: minimum bant genisligi garanti et (CBWFQ). kbps veya percent ile. Kuyruk icin ayrilan bant","sev":"i"},{"cat":"QoS","code":"bandwidth percent <1-100>","desc":"Policy-map class icinde: yuzde olarak minimum bant genisligi garantisi","sev":"i"},{"cat":"QoS","code":"bandwidth remaining percent <1-100>","desc":"Policy-map class icinde: kalan bant genisliginin yuzde kaçi bu class'a. Diger class'lar dolduktan sonra","sev":"i"},{"cat":"QoS","code":"priority <kbps>","desc":"Policy-map class icinde: LLQ (Low Latency Queuing). Ses/video icin strict priority kuyrugu. Garanti + dusuk gecikme","sev":"i"},{"cat":"QoS","code":"priority percent <1-100>","desc":"Policy-map class icinde: yuzde olarak LLQ priority. Voice icin genellikle %10-33 ayrılir","sev":"i"},{"cat":"QoS","code":"queue-limit <packets>","desc":"Policy-map class icinde: kuyruk derinligi (max paket sayisi). Dolunca tail-drop","sev":"i"},{"cat":"QoS","code":"fair-queue","desc":"Policy-map class icinde: WFQ (Weighted Fair Queuing) etkinlestir. Flow bazli adil kuyruk","sev":"i"},{"cat":"QoS","code":"random-detect","desc":"Policy-map class icinde: WRED (Weighted Random Early Detection) etkinlestir. Kuyruk dolmadan paket dusurur, TCP global sync onler","sev":"i"},{"cat":"QoS","code":"random-detect dscp-based","desc":"WRED DSCP bazli: farkli DSCP degerleri icin farkli drop threshold'lari. AF class'lari icin ideal","sev":"i"},{"cat":"QoS","code":"police <bps> <burst-normal> <burst-excess> conform-action transmit exceed-action drop","desc":"Traffic policing (rate limiting): bps hizi asarsa paket dusur. Token bucket algoritması. burst = burstable byte","sev":"i"},{"cat":"QoS","code":"police cir <bps> bc <bytes> be <bytes> conform-action transmit exceed-action set-dscp-transmit af11 violate-action drop","desc":"Uc renkli policing: conform=transmit, exceed=re-mark (ornegin AF dusur), violate=drop. Granular rate kontrol","sev":"i"},{"cat":"QoS","code":"police rate <value> bps","desc":"Modern policing syntax: rate 100m bps (100 Mbps). burst/peak opsiyonel. Daha okunabilir format","sev":"i"},{"cat":"QoS","code":"police rate percent <1-100>","desc":"Interface hizinin yuzdesi olarak policing. Interface hizi degisirse otomatik ayarlanir","sev":"i"},{"cat":"QoS","code":"shape average <bps>","desc":"Traffic shaping: ortalama hizi sinirla. Asim durumunda paketler kuyruge alinir (buffer), dusurulmez. WAN baglantilari icin ideal","sev":"i"},{"cat":"QoS","code":"shape average <bps> <burst-size>","desc":"Shaping burst boyutu ile: Bc (committed burst) tanimlama. Tc = Bc/CIR formulu ile interval hesaplanir","sev":"i"},{"cat":"QoS","code":"shape peak <bps>","desc":"Peak rate shaping: Bc + Be burst ile daha yuksek gecici hiz izni. shape average daha yaygin","sev":"i"},{"cat":"QoS","code":"interface GigabitEthernet0/0\n service-policy input <policy-name>","desc":"Policy-map'i interface'e giris yonunde uygula. Siniflandirma ve policing genellikle input'ta uygulanir","sev":"i"},{"cat":"QoS","code":"interface GigabitEthernet0/0\n service-policy output <policy-name>","desc":"Policy-map'i interface'e cikis yonunde uygula. Shaping ve queuing genellikle output'ta uygulanir","sev":"i"},{"cat":"QoS","code":"show policy-map","desc":"Tum policy-map konfigurasyonlari: class'lar, aksiyonlar, policing/shaping parametreleri","sev":"i"},{"cat":"QoS","code":"show policy-map interface <interface>","desc":"Interface'e uygulanan QoS istatistikleri: her class icin paket/byte sayisi, drop, police conform/exceed/violate","sev":"i"},{"cat":"QoS","code":"show policy-map interface <interface> input","desc":"Sadece input yonu policy istatistikleri","sev":"i"},{"cat":"QoS","code":"show policy-map interface <interface> output","desc":"Sadece output yonu policy istatistikleri: queue depth, tail drops, shaped rate","sev":"i"},{"cat":"QoS","code":"show class-map","desc":"Tum class-map konfigurasyonlari: match kriterleri, match-any/match-all","sev":"i"},{"cat":"QoS","code":"show mls qos","desc":"Global QoS durumu (Catalyst switch). Enabled/disabled ve trust boundary bilgisi","sev":"i"},{"cat":"QoS","code":"mls qos","desc":"Global QoS'u etkinlestir (Catalyst 3560/3750). Etkinlestirilmezse QoS config'leri calismaz!","sev":"i"},{"cat":"QoS","code":"mls qos trust dscp","desc":"Interface uzerinde DSCP trust. Gelen paketlerin DSCP degerine guven, yeniden yazma","sev":"i"},{"cat":"QoS","code":"mls qos trust cos","desc":"Interface uzerinde CoS trust. Trunk port'larda gelen CoS degerine guven","sev":"i"},{"cat":"QoS","code":"show auto qos","desc":"Auto-QoS konfigurasyonu ve durumu. auto qos voip komutu ile otomatik QoS sablonu uygulanir","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"snmp-server community <string> ro","desc":"SNMPv2c read-only community string. Monitoring araclari (Zabbix/PRTG/Nagios) bu community ile sorgular. Guvenlik icin ACL ekleyin","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"snmp-server community <string> rw","desc":"SNMPv2c read-write community string. SNMP ile konfigrasyon degisikligi yapilabilir! Cok dikkatli kullanin","sev":"w"},{"cat":"SNMP/Syslog/NTP","code":"snmp-server community <string> ro <acl-number>","desc":"ACL ile kisitlanmis SNMP community. Sadece ACL'deki IP'lerden SNMP sorgusu kabul et. Guvenlik best practice","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"snmp-server host <ip> version 2c <community>","desc":"SNMP trap/inform hedefi. Bu IP'ye SNMP notification gonderilir. version 2c veya 3","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"snmp-server host <ip> version 3 auth <username>","desc":"SNMPv3 trap hedefi. auth = authentication, priv = encryption. Guvenli SNMP icin v3 kullanin","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"snmp-server enable traps","desc":"Tum SNMP trap'leri etkinlestir. Belirli trap'ler icin: snmp-server enable traps bgp, snmp-server enable traps config","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"snmp-server enable traps snmp linkdown linkup","desc":"Interface up/down trap'lerini etkinlestir. NMS'te interface durum degisikligi bildirimi","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"snmp-server enable traps config","desc":"Konfigrasyon degisikligi trap'i. Cihaz config'i degistiginde NMS'e bildirim gonder","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"snmp-server enable traps envmon","desc":"Cevresel monitor trap'leri: sicaklik, fan, guc kaynagi alarmlari. Donanim saglik izleme","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"snmp-server location <text>","desc":"Cihaz fiziksel konumu (sysLocation OID). NMS'te gorunen konum bilgisi: 'Istanbul DC Rack-5'","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"snmp-server contact <text>","desc":"Cihaz sorumlusu iletisim bilgisi (sysContact OID). 'NOC - noc@company.com'","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"snmp-server chassis-id <text>","desc":"Cihaz chassis tanimlayicisi. Envanter yonetimi icin","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"snmp-server group <name> v3 priv","desc":"SNMPv3 grup olustur. priv = authentication + encryption. auth = sadece authentication. noauth = yok","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"snmp-server user <name> <group> v3 auth sha <auth-pass> priv aes 128 <priv-pass>","desc":"SNMPv3 kullanici olustur. SHA auth + AES-128 encryption. En guvenli SNMP yontemi","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"snmp-server view <name> iso included","desc":"SNMP view olustur: hangi MIB OID'lere erisim izni verilecek. iso = tum MIB tree. Kisitlama icin belirli OID kullanin","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"snmp-server ifindex persist","desc":"Interface ifIndex degerlerini kalici yap. Reboot sonrasi ifIndex degismez. SNMP monitoring tutarliligi icin","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"show snmp","desc":"SNMP istatistikleri: paket sayilari (get/set/trap), hata sayilari, community bilgisi","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"show snmp community","desc":"Tanimli SNMP community string'leri ve erisim seviyeleri","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"show snmp host","desc":"SNMP trap/inform hedef listesi ve istatistikleri","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"show snmp user","desc":"SNMPv3 kullanici listesi: isim, grup, auth/priv protokolleri","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"show snmp group","desc":"SNMPv3 grup listesi: isim, security model, read/write/notify view'lar","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"logging host <ip>","desc":"Syslog sunucusu tanimla. Loglar bu IP'ye UDP 514 ile gonderilir. Birden fazla host tanimlanabilir","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"logging host <ip> transport tcp port 1514","desc":"TCP transport ile syslog. UDP'den daha guvenilir. Port degistirilebilir. rsyslog/syslog-ng destekler","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"logging trap <level>","desc":"Syslog seviyesi: 0=emergencies, 1=alerts, 2=critical, 3=errors, 4=warnings, 5=notifications, 6=informational, 7=debugging. Remote syslog icin","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"logging buffered <size> <level>","desc":"Lokal log buffer: size=4096-2147483647 byte. level=seviye. 'logging buffered 65536 informational' onerilen","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"logging console <level>","desc":"Console'a log seviyesi. Production'da 'logging console warnings' veya kapatmak icin 'no logging console'","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"logging monitor <level>","desc":"VTY (SSH/Telnet) log seviyesi. 'terminal monitor' komutu ile aktif edilir","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"logging source-interface Loopback0","desc":"Syslog kaynak IP: Loopback0 kullan. Interface down olsa bile loglar dogru IP ile gider. Best practice","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"logging facility local7","desc":"Syslog facility degeri: local0-local7. Syslog sunucuda farkli dosyalara ayirmak icin kullanilir","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"logging discriminator <name> msg-body drops <regex>","desc":"Log filtresi: belirli mesajlari dusur. Gereksiz/gurultulu loglari filtrelemek icin. Regex destekler","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"service timestamps log datetime msec localtime show-timezone","desc":"Log mesajlarinda tarih/saat formatini ayarla. msec = milisaniye, localtime = yerel saat. Korelasyon icin kritik","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"service sequence-numbers","desc":"Log mesajlarina sira numarasi ekle. Kayip mesaj tespiti icin","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"show logging","desc":"Logging konfigurasyonu ve buffer'daki loglar: level, remote host, buffer icerigi. Troubleshooting ilk adim","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"show logging | include %LINK|%LINEPROTO","desc":"Interface up/down olaylarini filtrele. Hizli interface flap tespiti","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"clear logging","desc":"Log buffer'ini temizle. Mevcut loglar silinir! Yeni arastirma baslatmak icin","sev":"w"},{"cat":"SNMP/Syslog/NTP","code":"ntp server <ip>","desc":"NTP sunucusu tanimla. Cihaz bu sunucudan zaman senkronize eder. Birden fazla sunucu redundancy icin","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"ntp server <ip> prefer","desc":"Tercih edilen NTP sunucusu. Birden fazla sunucu varsa bu oncelikli olur","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"ntp server <ip> key <key-id>","desc":"NTP authentication key ile sunucu. MD5 ile dogrulama. Man-in-the-middle saldirilarini onler","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"ntp authenticate","desc":"NTP authentication'i etkinlestir. Authentication key tanimlanmis olmali","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"ntp authentication-key <id> md5 <key>","desc":"NTP authentication key olustur. Key-id ve MD5 sifre. NTP sunucu ve client'ta eslesmeli","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"ntp trusted-key <id>","desc":"Guvenilir NTP key ID. Sadece trusted key ile authentication basarili olur","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"ntp source Loopback0","desc":"NTP kaynak interface. NTP paketleri Loopback0 IP'si ile gonderilir. Best practice","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"ntp access-group peer <acl>","desc":"NTP erisim kontrolu: peer access-group ile kimlerin NTP sync yapabilecegini sinirla","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"ntp master <stratum>","desc":"Bu cihazi NTP master (server) yap. Stratum 1-15 (1=en yuksek). Internet'e erisimsiz ortamlarda","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"clock timezone <name> <hours-offset>","desc":"Saat dilimi ayarla. Ornek: clock timezone TRT 3 (Turkiye). Loglar ve NTP icin onemli","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"clock summer-time <name> recurring","desc":"Yaz saati uygulamasi otomatik. Recurring = her yil otomatik. Turkiye icin artik gereksiz (2016 sonrasi)","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"show ntp status","desc":"NTP senkronizasyon durumu: Clock is synchronized/unsynchronized, stratum, reference IP, offset (ms). offset < 100ms ideal","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"show ntp associations","desc":"NTP sunucu listesi: * = aktif, + = aday, - = reddedilmis. st = stratum, when = son sorgudan beri (saniye), poll = sorgu araligi","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"show ntp associations detail","desc":"NTP sunucu detayli: offset, delay, dispersion, jitter, reach (377 = son 8 sorgu basarili)","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"show clock","desc":"Cihaz saati. NTP senkron ise '*' isareti basinda gorulur. Senkron degilse '.' gorulur","sev":"i"},{"cat":"SNMP/Syslog/NTP","code":"show clock detail","desc":"Saat detayli: zaman kaynagi (NTP/user/hardware), saat dilimi, yaz saati durumu","sev":"i"},{"cat":"DHCP","code":"ip dhcp pool <name>","desc":"DHCP pool olustur. Router'i DHCP sunucusu olarak yapilandir. Pool ismi aciklayici olmali","sev":"i"},{"cat":"DHCP","code":"network <network> <mask>","desc":"DHCP pool icinde: dagitilacak IP araligi (subnet). Ornek: network 192.168.1.0 255.255.255.0","sev":"i"},{"cat":"DHCP","code":"network <network> /<prefix>","desc":"DHCP pool icinde: CIDR notasyonu ile subnet. Ornek: network 192.168.1.0 /24","sev":"i"},{"cat":"DHCP","code":"default-router <ip>","desc":"DHCP pool icinde: client'lara dagitilacak default gateway IP. Genellikle router'in kendi interface IP'si","sev":"i"},{"cat":"DHCP","code":"dns-server <ip1> [ip2]","desc":"DHCP pool icinde: DNS sunucu IP'leri. Birden fazla tanimlanabilir. Client'lar bu DNS'leri kullanir","sev":"i"},{"cat":"DHCP","code":"domain-name <domain>","desc":"DHCP pool icinde: domain adi. Client'lara dagitilir. Ornek: domain-name company.local","sev":"i"},{"cat":"DHCP","code":"lease <days> [hours] [minutes]","desc":"DHCP pool icinde: IP kiralama suresi. Default 1 gun. 0 = sonsuz (onerilen sadece statik cihazlar). lease 0 12 = 12 saat","sev":"i"},{"cat":"DHCP","code":"lease infinite","desc":"DHCP pool icinde: sonsuz kiralama suresi. IP asla expire olmaz. Printer/kamera gibi sabit cihazlar icin","sev":"i"},{"cat":"DHCP","code":"option 150 ip <tftp-server-ip>","desc":"DHCP Option 150: TFTP sunucu IP (Cisco IP Phone firmware icin). Cisco VoIP ortamlarinda sik kullanilir","sev":"i"},{"cat":"DHCP","code":"option 66 ascii <tftp-server-name>","desc":"DHCP Option 66: TFTP sunucu hostname veya IP. Genel PXE/TFTP boot senaryolari icin","sev":"i"},{"cat":"DHCP","code":"option 43 hex <hex-string>","desc":"DHCP Option 43: Vendor-specific bilgi. Wireless controller discovery (CAPWAP) icin sik kullanilir","sev":"i"},{"cat":"DHCP","code":"netbios-name-server <ip>","desc":"DHCP pool icinde: WINS sunucu IP. Eski Windows ortamlarinda NetBIOS name resolution icin","sev":"i"},{"cat":"DHCP","code":"ip dhcp excluded-address <start-ip> [end-ip]","desc":"DHCP'den haric tutulan IP araligi. Gateway, sunucu, printer gibi statik IP'li cihazlar icin. Pool olusturmadan ONCE tanimlayin","sev":"i"},{"cat":"DHCP","code":"ip dhcp excluded-address <single-ip>","desc":"Tek IP'yi DHCP'den haric tut. Genellikle default gateway IP'si haric tutulur","sev":"i"},{"cat":"DHCP","code":"ip helper-address <dhcp-server-ip>","desc":"Interface altinda: DHCP relay. Bu subnet'teki DHCP broadcast'leri belirtilen sunucuya unicast olarak iletilir. Farkli subnet'teki DHCP sunucu icin SART","sev":"i"},{"cat":"DHCP","code":"ip dhcp relay information option","desc":"DHCP Option 82 (relay agent info) ekle. DHCP snooping ile birlikte kullanilir. Hangi port/VLAN'dan geldigi bilgisi","sev":"i"},{"cat":"DHCP","code":"ip dhcp snooping","desc":"DHCP Snooping'i global olarak etkinlestir. Rogue DHCP sunucu saldirisini onler. Layer 2 guvenlik","sev":"i"},{"cat":"DHCP","code":"ip dhcp snooping vlan <vlan-id>","desc":"Belirli VLAN'da DHCP snooping etkinlestir","sev":"i"},{"cat":"DHCP","code":"ip dhcp snooping trust","desc":"Interface altinda: bu portu trusted yap. DHCP sunucusunun bagli oldugu port. Trusted olmayan portlardan DHCP offer dusurulur","sev":"i"},{"cat":"DHCP","code":"show ip dhcp binding","desc":"DHCP ile dagitilmis IP'ler: IP, MAC, lease expiry, type (automatic/manual). Hangi IP kime verilmis","sev":"i"},{"cat":"DHCP","code":"show ip dhcp pool","desc":"DHCP pool istatistikleri: toplam/kullanilan/bos adres sayisi, subnet, lease bilgisi. Adres tukenmesi kontrolu","sev":"i"},{"cat":"DHCP","code":"show ip dhcp pool <name>","desc":"Belirli DHCP pool detayi ve istatistikleri","sev":"i"},{"cat":"DHCP","code":"show ip dhcp conflict","desc":"DHCP IP catismalari: ayni IP birden fazla cihaz tarafindan kullaniliyorsa. Duplicate IP tespiti","sev":"i"},{"cat":"DHCP","code":"show ip dhcp server statistics","desc":"DHCP sunucu istatistikleri: discover/offer/request/ack sayilari. Sorun teshisi icin","sev":"i"},{"cat":"DHCP","code":"clear ip dhcp binding *","desc":"Tum DHCP binding'leri temizle. Client'lar yeniden IP alir. Adres havuzu yeniden kullanilabilir","sev":"w"},{"cat":"DHCP","code":"clear ip dhcp binding <ip>","desc":"Belirli IP'nin DHCP binding'ini temizle. O IP tekrar dagitilabilir hale gelir","sev":"i"},{"cat":"DHCP","code":"debug ip dhcp server events","desc":"DHCP sunucu olaylarini debug et: DISCOVER, OFFER, REQUEST, ACK/NAK mesajlari","sev":"w"},{"cat":"NAT","code":"interface GigabitEthernet0/0\n ip nat inside","desc":"Bu interface'i NAT inside (ic ag) olarak tanimla. Genellikle LAN tarafi","sev":"i"},{"cat":"NAT","code":"interface GigabitEthernet0/1\n ip nat outside","desc":"Bu interface'i NAT outside (dis ag) olarak tanimla. Genellikle WAN/Internet tarafi","sev":"i"},{"cat":"NAT","code":"ip nat inside source static <local-ip> <global-ip>","desc":"Statik NAT (1:1): ic IP'yi dis IP'ye kalici olarak esle. Sunucu yayinlamak icin. Bidirectional","sev":"i"},{"cat":"NAT","code":"ip nat inside source static tcp <local-ip> <local-port> <global-ip> <global-port>","desc":"Statik PAT (port forwarding): belirli port icin NAT. Ornek: ic web sunucusunun 80 portunu disari ac","sev":"i"},{"cat":"NAT","code":"ip nat inside source static tcp <local-ip> 80 interface GigabitEthernet0/1 80","desc":"Interface IP'si ile statik PAT. Dinamik WAN IP varsa interface kullanilir","sev":"i"},{"cat":"NAT","code":"ip nat pool <name> <start-ip> <end-ip> netmask <mask>","desc":"NAT pool olustur: dis IP adresi havuzu. Dinamik NAT ve PAT icin kullanilir","sev":"i"},{"cat":"NAT","code":"ip nat pool <name> <start-ip> <end-ip> prefix-length <prefix>","desc":"NAT pool prefix-length ile. netmask yerine CIDR. Ornek: prefix-length 24","sev":"i"},{"cat":"NAT","code":"ip nat inside source list <acl> pool <pool-name>","desc":"Dinamik NAT: ACL ile eslesen ic trafik, pool'daki dis IP'lerle eslenir. 1:1 ama gecici. Pool bitince yeni cevirme yapilamaz","sev":"i"},{"cat":"NAT","code":"ip nat inside source list <acl> pool <pool-name> overload","desc":"PAT (Port Address Translation): pool'daki IP'leri port bazli paylas. Cok sayida ic IP = az dis IP. En yaygin NAT yontemi","sev":"i"},{"cat":"NAT","code":"ip nat inside source list <acl> interface <intf> overload","desc":"PAT interface ile: WAN interface'inin IP'sini kullan. Tek dis IP ile tum ic ag internete cikar. SOHO'larda en yaygin","sev":"i"},{"cat":"NAT","code":"ip nat outside source static <outside-global> <outside-local>","desc":"Outside NAT: disaridan gelen IP'yi farkli bir ic IP'ye cevir. Ozel senaryolar icin","sev":"i"},{"cat":"NAT","code":"ip nat inside source route-map <name> interface <intf> overload","desc":"Route-map bazli NAT. ACL yerine route-map kullanilir. VRF-aware NAT veya policy-based NAT icin","sev":"i"},{"cat":"NAT","code":"show ip nat translations","desc":"Aktif NAT ceviri tablosu: inside local/global, outside local/global IP:port eslestirmesi. Ceviri dogrulamasi","sev":"i"},{"cat":"NAT","code":"show ip nat translations verbose","desc":"NAT ceviri detayli: timeout, kullanim zamani, flag'lar. Uzun sureli ceviri kontrolu","sev":"i"},{"cat":"NAT","code":"show ip nat statistics","desc":"NAT istatistikleri: aktif ceviri sayisi, hit sayisi, miss sayisi, expired. Pool doluluk orani. Miss yuksekse = ACL sorunu","sev":"i"},{"cat":"NAT","code":"clear ip nat translation *","desc":"Tum NAT ceviri tablosunu temizle. Aktif baglantilardaki ceviri silinir! Production'da dikkatli","sev":"e"},{"cat":"NAT","code":"clear ip nat translation inside <local-ip> <global-ip>","desc":"Belirli inside NAT cevirisini temizle","sev":"w"},{"cat":"NAT","code":"ip nat translation timeout <seconds>","desc":"NAT ceviri timeout suresi (saniye). Default 86400 (24 saat). Kisa timeout = daha az memory kullanimi","sev":"i"},{"cat":"NAT","code":"ip nat translation tcp-timeout <seconds>","desc":"TCP NAT timeout. Default 86400. Uzun sureli TCP baglantilari icin arttirilabilir","sev":"i"},{"cat":"NAT","code":"ip nat translation udp-timeout <seconds>","desc":"UDP NAT timeout. Default 300 (5 dakika). DNS gibi kisa UDP islemleri icin yeterli","sev":"i"},{"cat":"NAT","code":"debug ip nat","desc":"NAT islemlerini debug et: her paket icin inside/outside ceviri gorulur. Production'da DIKKATLI — yuksek CPU!","sev":"w"},{"cat":"NAT","code":"debug ip nat detailed","desc":"NAT detayli debug: neden cevirildi/cevirilmedi, hangi kural eslesti, hata detaylari","sev":"w"},{"cat":"BFD","code":"bfd interval <msec> min_rx <msec> multiplier <count>","desc":"Interface altinda BFD parametreleri: interval=gonderme araligi (ms), min_rx=minimum alma araligi (ms), multiplier=kac paket kaybinda down. Ornek: bfd interval 50 min_rx 50 multiplier 3 (150ms detect)","sev":"i"},{"cat":"BFD","code":"bfd echo","desc":"BFD echo mode etkinlestir. Forwarding path dogrulamasi icin echo paketleri gonderilir. Dusuk CPU overhead","sev":"i"},{"cat":"BFD","code":"no bfd echo","desc":"BFD echo mode devre disi. Asimetrik BFD veya multipoint icin gerekebilir","sev":"i"},{"cat":"BFD","code":"bfd slow-timers <msec>","desc":"BFD slow timer (saniye olarak da verilebilir). Control plane oturumu icin. Default 1000ms","sev":"i"},{"cat":"BFD","code":"bfd all-interfaces","desc":"Router altinda (OSPF/EIGRP/BGP): tum interface'lerde BFD etkinlestir. Tek tek interface yapilandirmaya gerek kalmaz","sev":"i"},{"cat":"BFD","code":"router ospf <process-id>\n bfd all-interfaces","desc":"OSPF ile BFD entegrasyonu. BFD down olursa OSPF komsulugu aninda duser. Hello timer'a bagli kalmaz","sev":"i"},{"cat":"BFD","code":"router eigrp <as>\n bfd all-interfaces","desc":"EIGRP ile BFD entegrasyonu. Sub-second failure detection","sev":"i"},{"cat":"BFD","code":"router bgp <as>\n neighbor <ip> fall-over bfd","desc":"BGP komsusunda BFD etkinlestir. BGP hold timer (default 180s) yerine BFD ile milisaniye seviyesinde tespit","sev":"i"},{"cat":"BFD","code":"ip route <prefix> <mask> <next-hop> track <number>\n ip sla <number>\n  icmp-echo <ip>","desc":"BFD static route tracking. IP SLA ile birlikte statik route'un gecerliligi izlenir","sev":"i"},{"cat":"BFD","code":"show bfd neighbors","desc":"BFD komsuluk tablosu: neighbor IP, interface, state (Up/Down), uptime, interval/multiplier. Hizli dogrulama","sev":"i"},{"cat":"BFD","code":"show bfd neighbors detail","desc":"BFD komsuluk detayi: RH (Remote Heard), Holdown timer, TX/RX interval, echo status, registered protocols","sev":"i"},{"cat":"BFD","code":"show bfd neighbors client <protocol>","desc":"Belirli protokol icin BFD komsu durumu. Ornek: show bfd neighbors client bgp","sev":"i"},{"cat":"BFD","code":"debug bfd event","desc":"BFD olaylarini debug: session up/down, parameter change. Komsuluk sorunlari icin","sev":"w"},{"cat":"EtherChannel","code":"interface range GigabitEthernet0/1-2\n channel-group <number> mode active","desc":"LACP active mode ile EtherChannel olustur. Active = LACP BPDU baslatir. number = port-channel numarasi (1-128)","sev":"i"},{"cat":"EtherChannel","code":"interface range GigabitEthernet0/1-2\n channel-group <number> mode passive","desc":"LACP passive mode: LACP BPDU'ya yanit verir ama baslatmaz. Karsi taraf active olmali. passive-passive = calisMAz!","sev":"i"},{"cat":"EtherChannel","code":"interface range GigabitEthernet0/1-2\n channel-group <number> mode desirable","desc":"PAgP desirable mode: PAgP negotiation baslatir. Cisco proprietary. Yeni tasarimlarda LACP (active) tercih edin","sev":"i"},{"cat":"EtherChannel","code":"interface range GigabitEthernet0/1-2\n channel-group <number> mode auto","desc":"PAgP auto mode: PAgP'ye yanit verir ama baslatmaz. Karsi taraf desirable olmali. auto-auto = calisMAz!","sev":"i"},{"cat":"EtherChannel","code":"interface range GigabitEthernet0/1-2\n channel-group <number> mode on","desc":"Static EtherChannel (no protocol). LACP/PAgP kullanmaz. Karsi taraf da 'on' olmali. Uyumsuzluk riski yuksek!","sev":"w"},{"cat":"EtherChannel","code":"interface Port-channel<number>","desc":"Port-channel logical interface. Trunk, IP, QoS gibi ayarlar burada yapilir (fiziksel interface'te degil)","sev":"i"},{"cat":"EtherChannel","code":"interface Port-channel1\n switchport mode trunk\n switchport trunk allowed vlan 10,20,30","desc":"Port-channel'i trunk olarak yapilandir. VLAN ayarlari port-channel interface altinda yapilir","sev":"i"},{"cat":"EtherChannel","code":"port-channel load-balance src-dst-ip","desc":"EtherChannel load-balance algoritması: src-dst-ip, src-dst-mac, src-ip, dst-ip, src-mac, dst-mac. Global config","sev":"i"},{"cat":"EtherChannel","code":"port-channel load-balance src-dst-ip-port","desc":"L4 port dahil load-balance. Daha iyi dagilim saglar. Platform destegi kontrol edin","sev":"i"},{"cat":"EtherChannel","code":"lacp system-priority <0-65535>","desc":"LACP system priority. Dusuk deger = yuksek oncelik. Hangi tarafin karar verici oldugunu belirler","sev":"i"},{"cat":"EtherChannel","code":"interface GigabitEthernet0/1\n lacp port-priority <0-65535>","desc":"LACP port priority. Dusuk = yuksek oncelik. Max port siniri asildığında hangi portlar aktif olacagini belirler","sev":"i"},{"cat":"EtherChannel","code":"lacp rate fast","desc":"Interface altinda: LACP PDU gonderme hizi. fast = 1 saniye (hizli fail detect). normal = 30 saniye (default)","sev":"i"},{"cat":"EtherChannel","code":"interface Port-channel1\n lacp max-bundle <count>","desc":"Port-channel'da aktif olabilecek max link sayisi. Kalan linkler standby olur. Hot-standby senaryosu","sev":"i"},{"cat":"EtherChannel","code":"interface Port-channel1\n lacp min-bundle <count>","desc":"Minimum aktif link sayisi. Bu sayinin altina duserse port-channel DOWN olur. Yetersiz bant genisligi onleme","sev":"i"},{"cat":"EtherChannel","code":"show etherchannel summary","desc":"EtherChannel ozeti: grup, port-channel, protokol (LACP/PAgP/none), member port'lar ve flag'lari. P=bundled, I=standalone, s=suspended","sev":"i"},{"cat":"EtherChannel","code":"show etherchannel detail","desc":"EtherChannel detay: her grubun member'lari, port state, LACP/PAgP parametreleri, istatistikler","sev":"i"},{"cat":"EtherChannel","code":"show etherchannel port-channel","desc":"Port-channel bilgileri: member sayisi, protocol, max-bundle, load-balance method","sev":"i"},{"cat":"EtherChannel","code":"show etherchannel load-balance","desc":"Load-balance algoritması ve hash distribution. Trafik dagitimini dogrulamak icin","sev":"i"},{"cat":"EtherChannel","code":"show lacp neighbor","desc":"LACP komsuluk bilgileri: system-id (MAC), port priority, key, state flags. Karsi taraf bilgileri","sev":"i"},{"cat":"EtherChannel","code":"show lacp neighbor detail","desc":"LACP komsu detayli: port state (Activity/Timeout/Aggregation/Synchronization/Collecting/Distributing)","sev":"i"},{"cat":"EtherChannel","code":"show lacp counters","desc":"LACP PDU sayaclari: LACP PDU sent/received, marker sent/received. Protokol calisiyor mu kontrolu","sev":"i"},{"cat":"EtherChannel","code":"show lacp sys-id","desc":"LACP system ID (priority + MAC). Karsi taraf ile eslestirme dogrulamasi","sev":"i"},{"cat":"EtherChannel","code":"show pagp neighbor","desc":"PAgP komsuluk bilgileri. PAgP kullaniliyorsa karsi taraf system-id ve port bilgileri","sev":"i"},{"cat":"EtherChannel","code":"show pagp counters","desc":"PAgP PDU sayaclari: sent/received/flush","sev":"i"},{"cat":"NX-OS","code":"feature vpc","desc":"NX-OS: vPC (Virtual Port Channel) feature'ini etkinlestir. Feature etkinlestirilmeden vpc komutlari kullanilamaz!","sev":"i"},{"cat":"NX-OS","code":"feature lacp","desc":"NX-OS: LACP feature'ini etkinlestir. Port-channel olusturmadan once gerekli","sev":"i"},{"cat":"NX-OS","code":"feature interface-vlan","desc":"NX-OS: SVI (VLAN interface) olusturma yetenegini etkinlestir","sev":"i"},{"cat":"NX-OS","code":"feature hsrp","desc":"NX-OS: HSRP feature'ini etkinlestir. IOS'ta otomatik aktiftir, NX-OS'ta 'feature' ile acilmali","sev":"i"},{"cat":"NX-OS","code":"feature ospf","desc":"NX-OS: OSPF feature'ini etkinlestir. NX-OS'ta her protokol ayri feature olarak acilir","sev":"i"},{"cat":"NX-OS","code":"feature bgp","desc":"NX-OS: BGP feature'ini etkinlestir","sev":"i"},{"cat":"NX-OS","code":"feature eigrp","desc":"NX-OS: EIGRP feature'ini etkinlestir","sev":"i"},{"cat":"NX-OS","code":"feature bfd","desc":"NX-OS: BFD feature'ini etkinlestir","sev":"i"},{"cat":"NX-OS","code":"feature nxapi","desc":"NX-OS: NX-API (REST API) etkinlestir. Programmatic erisim, otomasyon icin. HTTPS uzerinden JSON/XML/CLI","sev":"i"},{"cat":"NX-OS","code":"feature scp-server","desc":"NX-OS: SCP sunucu etkinlestir. Dosya transferi icin","sev":"i"},{"cat":"NX-OS","code":"feature bash-shell","desc":"NX-OS: Linux bash shell erisimi etkinlestir. run bash komutu ile gecis yapilir","sev":"i"},{"cat":"NX-OS","code":"show feature","desc":"NX-OS: tum feature'larin durumu (enabled/disabled). Hangi modullerin aktif oldugunu gor","sev":"i"},{"cat":"NX-OS","code":"vpc domain <id>","desc":"vPC domain olustur (1-1000). Iki Nexus switch arasinda vPC kurulumu icin ilk adim. Domain ID her iki switch'te ayni olmali","sev":"i"},{"cat":"NX-OS","code":"peer-keepalive destination <ip> source <ip>","desc":"vPC domain icinde: peer-keepalive link yapilandir. Management veya ayri L3 link uzerinden. Peer canli mi kontrolu","sev":"i"},{"cat":"NX-OS","code":"peer-keepalive destination <ip> source <ip> vrf management","desc":"vPC peer-keepalive management VRF uzerinden. En yaygin yapilandirma","sev":"i"},{"cat":"NX-OS","code":"role priority <value>","desc":"vPC domain icinde: role priority. Dusuk deger = primary. Primary role: MAC/STP/LACP kararlarinda oncelikli","sev":"i"},{"cat":"NX-OS","code":"system-priority <value>","desc":"vPC domain icinde: LACP system priority. Her iki switch'te ayni olmali","sev":"i"},{"cat":"NX-OS","code":"auto-recovery","desc":"vPC domain icinde: auto-recovery etkinlestir. Peer down ise vPC port'lari otomatik kurtarilir","sev":"i"},{"cat":"NX-OS","code":"delay restore <seconds>","desc":"vPC domain icinde: vPC port restore gecikmesi. Peer-link geri geldiginde hemen UP olmaz, routing tablosu oturmasini bekler","sev":"i"},{"cat":"NX-OS","code":"peer-switch","desc":"vPC domain icinde: peer-switch etkinlestir. Her iki switch STP root olarak davranir. STP convergence hizlanir","sev":"i"},{"cat":"NX-OS","code":"interface port-channel<id>\n vpc <vpc-id>","desc":"Port-channel'i vPC olarak tanimla. Karsi switch'te de ayni vpc-id kullanilmali. Downstream switch tek port-channel gorur","sev":"i"},{"cat":"NX-OS","code":"interface port-channel<id>\n vpc peer-link","desc":"Port-channel'i vPC peer-link olarak tanimla. Iki Nexus arasi kontrol + veri trafigi. Minimum 2x 10G onerilen","sev":"i"},{"cat":"NX-OS","code":"show vpc","desc":"vPC durumu: domain id, role (primary/secondary), peer status (alive/dead), vPC port durumu, consistency check","sev":"i"},{"cat":"NX-OS","code":"show vpc brief","desc":"vPC ozet: peer-link, vPC'ler, peer-keepalive, consistency durumu. Hizli durum kontrolu","sev":"i"},{"cat":"NX-OS","code":"show vpc peer-keepalive","desc":"vPC peer-keepalive durumu: status (alive/dead), destination IP, interval, timeout, son alinan mesaj zamani","sev":"i"},{"cat":"NX-OS","code":"show vpc consistency-parameters global","desc":"vPC global consistency check: STP mode, VLAN, MTU gibi parametrelerin her iki switch'te eslesmesi. Mismatch = vPC suspend!","sev":"i"},{"cat":"NX-OS","code":"show vpc consistency-parameters interface port-channel<id>","desc":"Belirli vPC port-channel'in consistency check sonucu. Type-1 mismatch = port suspend!","sev":"i"},{"cat":"NX-OS","code":"show vpc statistics peer-keepalive","desc":"vPC peer-keepalive istatistikleri: sent/received/missed mesaj sayilari","sev":"i"},{"cat":"NX-OS","code":"show vpc role","desc":"vPC role bilgisi: primary/secondary, operational role, system-mac","sev":"i"},{"cat":"NX-OS","code":"show vpc orphan-ports","desc":"vPC olmayan (orphan) portlari goster. Orphan port = sadece bir switch'e bagli. STP sorunlari olusturabilir","sev":"i"},{"cat":"NX-OS","code":"show port-channel summary","desc":"NX-OS: tum port-channel ozeti. IOS'taki 'show etherchannel summary' karsiligi. Member, protocol, status gorulur","sev":"i"},{"cat":"NX-OS","code":"show port-channel database","desc":"NX-OS: port-channel veritabani detay. Max-bundle, first-oper-port, last-bundle zamani","sev":"i"},{"cat":"NX-OS","code":"show system resources","desc":"NX-OS: CPU ve memory kullanimi. IOS'taki 'show processes cpu' + 'show processes memory' karsiligi. Process bazli detay","sev":"i"},{"cat":"NX-OS","code":"show system uptime","desc":"NX-OS: cihaz uptime. Son reboot zamani","sev":"i"},{"cat":"NX-OS","code":"show system internal","desc":"NX-OS: internal debug bilgileri. TAC case'lerinde istenir. show system internal sysmgr service all gibi","sev":"i"},{"cat":"NX-OS","code":"show hardware capacity","desc":"NX-OS: donanim kapasitesi: TCAM kullanimi, MAC tablosu, ARP tablosu, route tablosu dolulugu. Kapasite planlama","sev":"i"},{"cat":"NX-OS","code":"show module","desc":"NX-OS: modul bilgileri (supervisor, linecard). Status (ok/powered-up/fail), model, serial","sev":"i"},{"cat":"NX-OS","code":"show environment","desc":"NX-OS: fan, psu, sicaklik durumu. IOS'taki 'show environment all' karsiligi","sev":"i"},{"cat":"NX-OS","code":"show vlan brief","desc":"NX-OS: VLAN listesi ve port atamalari. Hizli VLAN kontrolu. IOS'taki ile ayni syntax","sev":"i"},{"cat":"NX-OS","code":"copy running-config startup-config","desc":"NX-OS: konfigi kaydet. IOS'taki ile ayni. Alternatif: 'copy r s' kisaltmasi","sev":"i"},{"cat":"NX-OS","code":"checkpoint <name>","desc":"NX-OS: konfigrasyon checkpoint olustur. Rollback icin. IOS'ta yok, NX-OS'a ozel ozellik","sev":"i"},{"cat":"NX-OS","code":"rollback running-config checkpoint <name>","desc":"NX-OS: checkpoint'e geri don. Yanlis konfigrasyon sonrasi hizli geri alma. Cok faydali!","sev":"w"},{"cat":"NX-OS","code":"show diff rollback-patch checkpoint <name> running-config","desc":"NX-OS: checkpoint ile mevcut konfig arasindaki farklari goster. Rollback oncesi ne degisecegini gor","sev":"i"},{"cat":"NX-OS","code":"run bash","desc":"NX-OS: Linux bash shell'e gec (feature bash-shell gerekli). Linux komutlari calilstir","sev":"i"},{"cat":"Device Mgmt","code":"show version","desc":"IOS/NX-OS surumu, uptime, donanim modeli, seri no, flash/memory boyutu, boot image, config register. En temel bilgi komutu","sev":"i"},{"cat":"Device Mgmt","code":"show inventory","desc":"Donanim envanter: PID (product ID), VID (version), SN (seri no). Her modul, PSU, fan, SFP icin. RMA/garanti kontrolu","sev":"i"},{"cat":"Device Mgmt","code":"show running-config","desc":"Calisma konfigurasyonu (RAM'de). Aktif konfig. 'show run | section <keyword>' ile filtreleme yapilabilir","sev":"i"},{"cat":"Device Mgmt","code":"show running-config | section interface","desc":"Konfigi bolum bazli filtrele: interface, router ospf, line vty, crypto map. En faydali filtre","sev":"i"},{"cat":"Device Mgmt","code":"show running-config | include <keyword>","desc":"Konfig'de anahtar kelime ara. include = iceren satirlari goster. Hizli konfig kontrolu","sev":"i"},{"cat":"Device Mgmt","code":"show running-config | begin <keyword>","desc":"Konfig'de anahtar kelimeden baslayarak goster. Uzun konfig'de belirli noktaya git","sev":"i"},{"cat":"Device Mgmt","code":"show startup-config","desc":"Kaydedilmis konfigrasyon (NVRAM/flash'ta). Reboot sonrasi bu konfig yuklenir. Running ile farkliysa = kaydedilmemis degisiklik var","sev":"i"},{"cat":"Device Mgmt","code":"copy running-config startup-config","desc":"Calisma konfigurasyonunu kaydet. Kisaltma: 'wr' veya 'copy run start'. Her degisiklik sonrasi calistirin!","sev":"i"},{"cat":"Device Mgmt","code":"write memory","desc":"Konfigurasyonu kaydet. 'copy running-config startup-config' ile ayni. Kisaltma: 'wr mem' veya sadece 'wr'","sev":"i"},{"cat":"Device Mgmt","code":"copy running-config tftp://<server>/<filename>","desc":"Konfigi TFTP sunucuya yedekle. Uzak yedekleme icin. SCP, FTP de desteklenir","sev":"i"},{"cat":"Device Mgmt","code":"copy tftp://<server>/<filename> running-config","desc":"TFTP'den konfig yukle (merge). Dikkat: mevcut konfig'e EKLENIR, EZMEZ! Startup-config'e yukleme tamamen ezer","sev":"w"},{"cat":"Device Mgmt","code":"show processes cpu","desc":"CPU kullanimi: 5 saniye / 1 dakika / 5 dakika ortalamalari + en cok CPU kullanan process listesi. %80+ = sorun","sev":"i"},{"cat":"Device Mgmt","code":"show processes cpu sorted","desc":"CPU kullanimi yuksekten dusuge siralanmis. Hangi process'in CPU yedigini hizla bulmak icin","sev":"i"},{"cat":"Device Mgmt","code":"show processes cpu history","desc":"CPU kullanimi grafik/tarihce. Son 60 saniye, 60 dakika, 72 saat. Trend analizi","sev":"i"},{"cat":"Device Mgmt","code":"show processes memory sorted","desc":"Memory kullanimi: process bazli, yuksekten dusuge. Memory leak tespiti","sev":"i"},{"cat":"Device Mgmt","code":"show processes memory platform sorted","desc":"Platform memory kullanimi (IOS-XE). IOSd, Linux kernel, IOMD process'leri","sev":"i"},{"cat":"Device Mgmt","code":"show interfaces","desc":"Tum interface'lerin durumu ve istatistikleri: status, speed, duplex, errors, CRC, collisions, drops, throughput","sev":"i"},{"cat":"Device Mgmt","code":"show interfaces <interface>","desc":"Belirli interface detayi: packets in/out, errors, CRC, frame, overrun, ignored, output drops. Sorun teshisi icin","sev":"i"},{"cat":"Device Mgmt","code":"show interfaces status","desc":"Interface ozet tablosu: port, name, status (connected/notconnect/disabled), VLAN, duplex, speed, type","sev":"i"},{"cat":"Device Mgmt","code":"show interfaces trunk","desc":"Trunk port listesi: native VLAN, allowed VLAN, active VLAN. Trunk konfigrasyon dogrulamasi","sev":"i"},{"cat":"Device Mgmt","code":"show interfaces counters errors","desc":"Interface hata sayaclari ozeti. CRC, input/output errors, underruns, overruns. Fiziksel sorun tespiti","sev":"i"},{"cat":"Device Mgmt","code":"show ip interface brief","desc":"IP interface ozeti: interface, IP, OK?, Method, Status, Protocol. Hizli IP ve durum kontrolu. En sik kullanilan komut","sev":"i"},{"cat":"Device Mgmt","code":"show ip route","desc":"Routing tablosu: connected (C), static (S), OSPF (O), EIGRP (D), BGP (B), RIP (R). Next-hop, metric, interface","sev":"i"},{"cat":"Device Mgmt","code":"show ip route <prefix>","desc":"Belirli prefix icin route detayi: next-hop, metric, administrative distance, last update, via interface","sev":"i"},{"cat":"Device Mgmt","code":"show ip arp","desc":"ARP tablosu: IP, MAC, Age (dakika), VLAN/interface. L2-L3 eslesmesi. Age 0 = yeni, - = statik","sev":"i"},{"cat":"Device Mgmt","code":"show mac address-table","desc":"MAC adres tablosu: VLAN, MAC, type (dynamic/static), port. Cihaz hangi portta kontrolu","sev":"i"},{"cat":"Device Mgmt","code":"show mac address-table address <mac>","desc":"Belirli MAC adresinin hangi port'ta oldugunu bul. Cihaz lokasyonu tespiti","sev":"i"},{"cat":"Device Mgmt","code":"show cdp neighbors","desc":"CDP komsu listesi: cihaz adi, local interface, hold time, capability (R=router, S=switch), platform, remote port. Cisco cihaz topolojisi","sev":"i"},{"cat":"Device Mgmt","code":"show cdp neighbors detail","desc":"CDP komsu detay: management IP, IOS versiyon, VTP domain, duplex. Kapsamli komsu bilgisi","sev":"i"},{"cat":"Device Mgmt","code":"show lldp neighbors","desc":"LLDP komsu listesi. CDP'nin vendor-neutral versiyonu. Non-Cisco cihazlar icin onemli (Linux, HP, Juniper)","sev":"i"},{"cat":"Device Mgmt","code":"show lldp neighbors detail","desc":"LLDP komsu detay: system name, management IP, capabilities, port description","sev":"i"},{"cat":"Device Mgmt","code":"show tech-support","desc":"Tam troubleshooting raporu: show version, show running-config, show interfaces, show ip route, show processes, show logging... TAC case'leri icin","sev":"i"},{"cat":"Device Mgmt","code":"show tech-support | redirect tftp://<server>/tech.txt","desc":"Tech-support ciktisini TFTP'ye kaydet. Buyuk cikti (MB'larca). TAC'e gondermek icin","sev":"i"},{"cat":"Device Mgmt","code":"terminal monitor","desc":"VTY (SSH/Telnet) session'da log mesajlarini goster. Default olarak sadece console'da gorulur. Debug icin SART","sev":"i"},{"cat":"Device Mgmt","code":"terminal no monitor","desc":"VTY session'da log mesajlarini kapat. Debug bitince kapatmayi unutmayin","sev":"i"},{"cat":"Device Mgmt","code":"undebug all","desc":"Tum debug'lari kapat. Debug CPU tuketir! Bitince MUTLAKA kapatin. Kisaltma: 'u all'","sev":"i"},{"cat":"Device Mgmt","code":"debug ip packet","desc":"IP paket debug. Her paketi loglar. DIKKAT: production'da CPU %100'e cikabilir! ACL filtresi kullanin","sev":"e"},{"cat":"Device Mgmt","code":"debug ip packet <acl-number>","desc":"ACL filtreli IP debug. Sadece ACL ile eslesen paketler loglanir. Production'da debug icin ZORUNLU","sev":"w"},{"cat":"Device Mgmt","code":"debug ip icmp","desc":"ICMP (ping) debug: ICMP echo/reply/unreachable mesajlari. Ping sorunlari icin","sev":"i"},{"cat":"Device Mgmt","code":"show environment all","desc":"Cevresel durumu: PSU durumu (ok/fail), fan RPM, sicaklik (derece). Donanim sagligi izleme","sev":"i"},{"cat":"Device Mgmt","code":"show environment power","desc":"Guc kaynagi durumu: watt, state, input voltage. UPS sorunlari, PSU ariza tespiti","sev":"i"},{"cat":"Device Mgmt","code":"show environment temperature","desc":"Sicaklik sensoru okumalari. Alarm threshold'lari. Overheating = shutdown riski!","sev":"i"},{"cat":"Device Mgmt","code":"show flash:","desc":"Flash (dahili depolama) icerigi: IOS image, konfig dosyalari, dosya boyutlari. Flash dolu ise yeni image yuklenemez","sev":"i"},{"cat":"Device Mgmt","code":"dir flash:","desc":"Flash dizin listesi. Dosya adi, boyut, tarih. 'show flash:' ile benzer","sev":"i"},{"cat":"Device Mgmt","code":"show boot","desc":"Boot degiskenleri: hangi IOS image'dan boot ediliyor, config-register degeri, boot system komutu","sev":"i"},{"cat":"Device Mgmt","code":"reload","desc":"Cihazi yeniden baslat. Aktif trafik KESILIR! Zamanli reload icin: 'reload in 5' (5 dakika sonra)","sev":"e"},{"cat":"Device Mgmt","code":"reload in <minutes>","desc":"Zamanli reload: belirtilen dakika sonra reboot. 'reload cancel' ile iptal edilir. Uzak konfig icin guvenlik","sev":"w"},{"cat":"Device Mgmt","code":"reload cancel","desc":"Zamanlanmis reload'u iptal et. Uzak erisimi kaybetme riski olan konfig'lerde guvenlik agi","sev":"i"},{"cat":"Device Mgmt","code":"event manager applet <name>","desc":"EEM (Embedded Event Manager) applet olustur. Olay bazli otomatik aksiyonlar. Belirli bir olay olunca komut calistir","sev":"i"},{"cat":"Device Mgmt","code":"event syslog pattern \"<regex>\"","desc":"EEM trigger: syslog mesajinda pattern eslesmesi. Ornek: interface down mesaji geldiginde aksiyon al","sev":"i"},{"cat":"Device Mgmt","code":"event timer watchdog time <seconds>","desc":"EEM trigger: belirli araliklarla calis (timer). Periodic kontrol gorevi icin","sev":"i"},{"cat":"Device Mgmt","code":"event timer cron cron-entry \"0 2 * * *\"","desc":"EEM trigger: cron zamanlama. Her gun saat 02:00'de calis gibi. Zamanlanmis gorevler","sev":"i"},{"cat":"Device Mgmt","code":"event track <track-number> state down","desc":"EEM trigger: IP SLA / track durumu degisince. Route veya link down olaylarini yakala","sev":"i"},{"cat":"Device Mgmt","code":"event interface name <intf> parameter input_errors entry-op gt entry-val 100 poll-interval 60","desc":"EEM trigger: interface hata sayisi threshold'u asinca. Proaktif donanim sorun tespiti","sev":"i"},{"cat":"Device Mgmt","code":"action 1.0 cli command \"enable\"","desc":"EEM action: CLI komutu calistir. Sirasiyla: enable, conf t, komutlar. Her action numarali olmali","sev":"i"},{"cat":"Device Mgmt","code":"action 2.0 cli command \"show ip interface brief\"","desc":"EEM action ornegi: show komutu calistir ve ciktiyi logla","sev":"i"},{"cat":"Device Mgmt","code":"action 3.0 syslog msg \"EEM: Interface error threshold exceeded\"","desc":"EEM action: syslog mesaji olustur. Ozel alarm/bildirim icin","sev":"i"},{"cat":"Device Mgmt","code":"action 4.0 mail server <smtp-ip> to <email> subject \"Alert\" body \"$_cli_result\"","desc":"EEM action: email gonder. SMTP sunucu ve alici adresi. CLI cikti sonucu body'de gonderilebilir","sev":"i"},{"cat":"Device Mgmt","code":"archive","desc":"Archive modu: konfigrasyon otomatik yedekleme ve degisiklik loglama yapilandirmasi","sev":"i"},{"cat":"Device Mgmt","code":"path tftp://<server>/archive/$h-","desc":"Archive icinde: yedek dosya yolu. $h = hostname. Otomatik versiyon numarasi eklenir","sev":"i"},{"cat":"Device Mgmt","code":"write-memory","desc":"Archive icinde: 'write memory' calistiginda otomatik yedek al","sev":"i"},{"cat":"Device Mgmt","code":"time-period <minutes>","desc":"Archive icinde: belirli aralikla otomatik yedek al (dakika)","sev":"i"},{"cat":"Device Mgmt","code":"maximum <count>","desc":"Archive icinde: maksimum yedek sayisi. Eski yedekler otomatik silinir","sev":"i"},{"cat":"Device Mgmt","code":"log config","desc":"Archive icinde: konfigrasyon degisiklik loglama. Kim, ne, ne zaman degistirdi","sev":"i"},{"cat":"Device Mgmt","code":"show archive","desc":"Archive yedek listesi: dosya adi, tarih. Onceki konfigrasyon versiyonlari","sev":"i"},{"cat":"Device Mgmt","code":"show archive log config all","desc":"Konfigrasyon degisiklik gecmisi: tarih, kullanici, komut. Audit trail. Kim ne degistirmis?","sev":"i"},{"cat":"Device Mgmt","code":"kron occurrence <name> at <hh:mm> <day> <month> recurring","desc":"Kron: zamanlanmis gorev olustur. Belirli tarih/saatte komut calistir. NX-OS'ta 'scheduler' karsiligi","sev":"i"},{"cat":"Device Mgmt","code":"kron policy-list <name>\n cli show running-config | redirect tftp://<server>/backup.cfg","desc":"Kron policy: calistirilacak komut(lar). Zamanli yedekleme ornegi","sev":"i"},{"cat":"Security","code":"enable secret <password>","desc":"Enable (privileged EXEC) sifresi. MD5/SHA ile hash'lenir. 'enable password' plaintext — KULLANMAYIN!","sev":"i"},{"cat":"Security","code":"enable algorithm-type sha256 secret <password>","desc":"SHA-256 ile enable secret. MD5'ten daha guvenli. IOS 15.3+ ve IOS-XE destekler","sev":"i"},{"cat":"Security","code":"service password-encryption","desc":"Konfig dosyasindaki plaintext sifreleri sifrele (Type 7). Gercek guvenlik degil — kolayca kirilir! Ama yine de acik","sev":"i"},{"cat":"Security","code":"username <name> privilege <0-15> secret <password>","desc":"Lokal kullanici olustur. privilege: 0=minimum, 1=default user, 15=full admin. secret = hash'lenir","sev":"i"},{"cat":"Security","code":"username <name> algorithm-type sha256 secret <password>","desc":"SHA-256 ile kullanici sifresi. Daha guvenli hash. IOS 15.3+ gerekli","sev":"i"},{"cat":"Security","code":"username <name> privilege 15 secret <password>","desc":"Admin kullanicisi olustur. privilege 15 = tam yetki. SSH ile giris icin","sev":"i"},{"cat":"Security","code":"line console 0\n login local\n exec-timeout 5 0","desc":"Console port: lokal kullanici ile giris, 5 dakika inactivity timeout. Fiziksel erisim guvenligi","sev":"i"},{"cat":"Security","code":"line vty 0 15\n login local\n transport input ssh","desc":"VTY (uzak erisim): lokal kullanici ile giris, SADECE SSH izin ver (Telnet yok!). 16 esanli session (0-15)","sev":"i"},{"cat":"Security","code":"line vty 0 15\n access-class <acl> in","desc":"VTY erisim kontrolu: ACL ile hangi IP'lerden SSH/Telnet yapilabilecegini sinirla. Guvenlik best practice","sev":"i"},{"cat":"Security","code":"line vty 0 15\n exec-timeout <minutes> <seconds>","desc":"VTY session timeout. Inaktif session'lari otomatik kapat. 'exec-timeout 10 0' = 10 dakika. 0 0 = timeout yok (TEHLIKELI!)","sev":"i"},{"cat":"Security","code":"line aux 0\n no exec\n transport input none","desc":"AUX port'u devre disi birak. Kullanilmiyorsa kapatilmali. Fiziksel saldiri vektoru","sev":"i"},{"cat":"Security","code":"ip ssh version 2","desc":"Sadece SSH version 2 kullan. SSHv1 guvenlik aciklari var! Global config","sev":"i"},{"cat":"Security","code":"crypto key generate rsa modulus 2048","desc":"RSA key pair olustur. SSH icin ZORUNLU. modulus: 1024 (minimum), 2048 (onerilen), 4096 (en guvenli)","sev":"i"},{"cat":"Security","code":"ip ssh time-out 60","desc":"SSH baglanti timeout (saniye). Authentication suresi sinirlamasi","sev":"i"},{"cat":"Security","code":"ip ssh authentication-retries 3","desc":"SSH authentication deneme limiti. Brute-force saldirisi yaveslatir","sev":"i"},{"cat":"Security","code":"aaa new-model","desc":"AAA (Authentication, Authorization, Accounting) framework'unu etkinlestir. RADIUS/TACACS+ icin ZORUNLU. Etkinlesince login davranisi degisir!","sev":"w"},{"cat":"Security","code":"aaa authentication login default group tacacs+ local","desc":"Login authentication: once TACACS+ dene, basarisizsa lokal kullanici. default = tum line'lar icin gecerli","sev":"i"},{"cat":"Security","code":"aaa authentication login default group radius local","desc":"Login authentication: once RADIUS dene, basarisizsa lokal. RADIUS daha yaygin (WiFi, VPN)","sev":"i"},{"cat":"Security","code":"aaa authentication login default local","desc":"Sadece lokal authentication. RADIUS/TACACS+ yok. Kucuk ortamlar icin","sev":"i"},{"cat":"Security","code":"aaa authentication login CONSOLE local","desc":"Ozel method list: CONSOLE isimli list, sadece lokal auth. 'line console 0' altinda 'login authentication CONSOLE' ile kullanilir","sev":"i"},{"cat":"Security","code":"aaa authorization exec default group tacacs+ local","desc":"EXEC authorization: kullanicinin privilege seviyesini TACACS+ sunucudan al. Komut yetkisi kontrolu","sev":"i"},{"cat":"Security","code":"aaa authorization commands 15 default group tacacs+ local","desc":"Komut authorization: privilege 15 komutlarini TACACS+ ile dogrula. Kim hangi komutu calistirabilir","sev":"i"},{"cat":"Security","code":"aaa accounting exec default start-stop group tacacs+","desc":"EXEC session accounting: giris/cikis zamani, kullanici, IP. Audit trail","sev":"i"},{"cat":"Security","code":"aaa accounting commands 15 default start-stop group tacacs+","desc":"Komut accounting: privilege 15 icin calistirilan her komut loglanir. Forensic analiz icin","sev":"i"},{"cat":"Security","code":"radius-server host <ip> key <shared-secret>","desc":"RADIUS sunucu tanimla. Key = paylasilan sifre (sunucu ile ayni olmali). Eski syntax (IOS 12/15)","sev":"i"},{"cat":"Security","code":"radius server <name>\n address ipv4 <ip> auth-port 1812 acct-port 1813\n key <shared-secret>","desc":"RADIUS sunucu tanimla (modern syntax). Auth port 1812, accounting port 1813 (veya 1645/1646 eski)","sev":"i"},{"cat":"Security","code":"tacacs-server host <ip> key <shared-secret>","desc":"TACACS+ sunucu tanimla. TACACS+ = Cisco gelistirdi, komut authorization destekler. TCP 49 kullanir (RADIUS=UDP)","sev":"i"},{"cat":"Security","code":"tacacs server <name>\n address ipv4 <ip>\n key <shared-secret>","desc":"TACACS+ sunucu tanimla (modern syntax). Cisco ISE, FreeRADIUS, TACACS+ daemon ile kullanilir","sev":"i"},{"cat":"Security","code":"ip radius source-interface Loopback0","desc":"RADIUS paketleri icin kaynak interface. Loopback = stabil IP. Sunucuda bu IP'ye izin verilmis olmali","sev":"i"},{"cat":"Security","code":"ip tacacs source-interface Loopback0","desc":"TACACS+ kaynak interface. Best practice: Loopback kullanin","sev":"i"},{"cat":"Security","code":"aaa group server tacacs+ <name>\n server-private <ip> key <key>","desc":"TACACS+ sunucu grubu olustur. Birden fazla sunucu redundancy icin. server-private ile sunucu bazli key","sev":"i"},{"cat":"Security","code":"test aaa group tacacs+ <user> <pass> new-code","desc":"AAA authentication testi. Sunucu baglantisini ve kullanici dogrulamasini test et. Troubleshooting icin cok faydali","sev":"i"},{"cat":"Security","code":"switchport port-security","desc":"Interface altinda port security etkinlestir. Oncesinde 'switchport mode access' olmali! MAC bazli erisim kontrolu","sev":"i"},{"cat":"Security","code":"switchport port-security maximum <count>","desc":"Portta izin verilen max MAC adresi sayisi. Default 1. Birden fazla cihaz bagliysa (IP phone+PC) arttirilmali","sev":"i"},{"cat":"Security","code":"switchport port-security mac-address sticky","desc":"Sticky MAC: dinamik ogrenilenMAC'leri running-config'e kaydet. Reboot sonrasi korumak icin 'wr mem' yapin","sev":"i"},{"cat":"Security","code":"switchport port-security mac-address <mac>","desc":"Statik MAC adresi tanimla. Sadece bu MAC adresine izin ver. Format: xxxx.xxxx.xxxx","sev":"i"},{"cat":"Security","code":"switchport port-security violation shutdown","desc":"Ihlal aksiyonu: shutdown (default) = portu err-disabled yapar. restrict = paket dusur+log, protect = sadece dusur","sev":"i"},{"cat":"Security","code":"switchport port-security violation restrict","desc":"Ihlal aksiyonu: restrict = izinsiz MAC paketleri dusurulur, syslog mesaji olusturulur, SNMP trap gonderilir. Port kapanmaz","sev":"i"},{"cat":"Security","code":"switchport port-security violation protect","desc":"Ihlal aksiyonu: protect = izinsiz MAC paketleri sessizce dusurulur. Log yok, SNMP yok. En az bilgilendirici","sev":"i"},{"cat":"Security","code":"switchport port-security aging time <minutes>","desc":"MAC adresi yaslanma suresi. Belirtilen sure sonra MAC silinir, yeni MAC ogrenilebilir","sev":"i"},{"cat":"Security","code":"show port-security","desc":"Port security ozeti: interface, max MAC, current count, security violation count, security action","sev":"i"},{"cat":"Security","code":"show port-security interface <interface>","desc":"Belirli interface'in port security detayi: status, violation mode, aging, max/total/configured addresses","sev":"i"},{"cat":"Security","code":"show port-security address","desc":"Port security MAC adresi tablosu: VLAN, MAC, type (static/sticky/dynamic), port, remaining age","sev":"i"},{"cat":"Security","code":"errdisable recovery cause psecure-violation","desc":"Port security ihlali sonrasi err-disabled portu otomatik kurtarma. Belirli sure sonra port tekrar UP olur","sev":"i"},{"cat":"Security","code":"errdisable recovery interval <seconds>","desc":"Err-disabled recovery suresi (saniye). Default 300 (5 dakika). Port otomatik tekrar etkinlesir","sev":"i"},{"cat":"Security","code":"ip verify unicast source reachable-via rx","desc":"uRPF Strict mode: kaynak IP'nin bu interface uzerinden ulasilabilir oldugunu dogrula. IP spoofing onleme. 'rx' = strict","sev":"i"},{"cat":"Security","code":"ip verify unicast source reachable-via any","desc":"uRPF Loose mode: kaynak IP'nin routing tablosunda herhangi bir route ile ulasilabilir oldugunu dogrula. 'any' = loose","sev":"i"},{"cat":"Security","code":"ip verify unicast source reachable-via rx allow-default","desc":"uRPF Strict + default route izni. Default route varsa tum kaynak IP'ler gecerli sayilir. Dikkatli kullanin","sev":"i"},{"cat":"Security","code":"login block-for <seconds> attempts <count> within <seconds>","desc":"Login brute-force korumasi: belirtilen sure icinde X basarisiz deneme olursa giris Y saniye engellenir. Ornek: login block-for 120 attempts 3 within 60","sev":"i"},{"cat":"Security","code":"login on-failure log","desc":"Basarisiz giris denemelerini logla. Saldiri tespiti icin","sev":"i"},{"cat":"Security","code":"login on-success log","desc":"Basarili giris olaylarini logla. Audit trail icin","sev":"i"},{"cat":"Security","code":"security passwords min-length <length>","desc":"Minimum sifre uzunlugu (1-16 karakter). Zayif sifre kullanimi onleme","sev":"i"},{"cat":"Security","code":"banner motd # <message> #","desc":"MOTD (Message of the Day) banner. Giris oncesi yasal uyari mesaji. 'Yetkisiz erisim yasaktir' gibi. Delimiters: # veya ^C","sev":"i"},{"cat":"Security","code":"banner login # <message> #","desc":"Login banner: kullanici adi/sifre istenmeden once gosterilir. Yasal uyari icin","sev":"i"},{"cat":"Security","code":"no ip http server","desc":"HTTP sunucuyu devre disi birak. Web arayuzu guvenlik riski. Kullanilmiyorsa kapatin","sev":"i"},{"cat":"Security","code":"no ip http secure-server","desc":"HTTPS sunucuyu devre disi birak (gerekli degilse). REST API veya web GUI kullanilmiyorsa","sev":"i"},{"cat":"Security","code":"no cdp run","desc":"CDP'yi global olarak devre disi birak. Bilgi sizintisi onleme. Internet'e bakan interface'lerde en azindan 'no cdp enable' kullanin","sev":"i"},{"cat":"Security","code":"no ip source-route","desc":"IP source routing'i devre disi birak. Saldirgan paket yolunu belirleyebilir. Guvenlik best practice","sev":"i"},{"cat":"Security","code":"no ip proxy-arp","desc":"Interface altinda proxy ARP'yi devre disi birak. ARP spoofing riskini azaltir. Gereksiz yere acik olmamali","sev":"i"},{"cat":"Security","code":"ip access-list standard <name>","desc":"Standard ACL (kaynak IP bazli). Basit filtreler, VTY erisim kontrolu, route-map icin. Named ACL onerilen","sev":"i"},{"cat":"Security","code":"ip access-list extended <name>","desc":"Extended ACL (kaynak/hedef IP, port, protokol). Detayli trafik filtreleme. Named ACL onerilen","sev":"i"},{"cat":"Security","code":"show access-lists","desc":"Tum ACL'lerin konfigurasyonu ve hit count. Hangi kural kac kez eslesti gorulur","sev":"i"},{"cat":"Security","code":"show ip access-lists","desc":"IP ACL'leri detayli: sequence number, rule, matches. Hit count sifirsa = kullanilmiyor olabilir","sev":"i"},{"cat":"Ping/Trace","code":"ping <ip>","desc":"Basit ICMP ping. ! = basarili, . = timeout, U = unreachable. 5 paket gonderir. Temel baglanti testi","sev":"i"},{"cat":"Ping/Trace","code":"ping <ip> source <source-ip-or-intf>","desc":"Kaynak IP/interface belirterek ping. VPN/loopback testi icin KRITIK. Varsayilan cikis interface IP'si kullanilir","sev":"i"},{"cat":"Ping/Trace","code":"ping <ip> size <bytes>","desc":"Ping paket boyutu. Default 100 byte. MTU testi icin: size 1500 df-bit. Buyuk paket gecmiyor = MTU sorunu","sev":"i"},{"cat":"Ping/Trace","code":"ping <ip> repeat <count>","desc":"Tekrar sayisi. Default 5. Uzun test: repeat 1000. Paket kaybi orani tespiti icin","sev":"i"},{"cat":"Ping/Trace","code":"ping <ip> timeout <seconds>","desc":"Timeout suresi (sn). Default 2. Yuksek latency ortaminda artirin. WAN/uydu linkleri icin timeout 5","sev":"i"},{"cat":"Ping/Trace","code":"ping <ip> df-bit","desc":"Don't Fragment biti ayarla. MTU path discovery icin: size 1500 df-bit. 'DF set' ile fragmentation engellenir, buyuk paket gecmezse MTU sorunlu","sev":"i"},{"cat":"Ping/Trace","code":"ping <ip> size 1500 df-bit source <intf>","desc":"MTU testi: 1500 byte, fragmentation yok, belirli kaynak. Basarisizsa MTU < 1500. Boyutu dusurerek min MTU bulun","sev":"i"},{"cat":"Ping/Trace","code":"ping <ip> sweep 1400 1500 10","desc":"Sweep ping: 1400'den 1500'e 10'ar artarak farkli boyutlarda ping at. MTU kesfetme icin ideal. Hangi boyutta fail olur?","sev":"i"},{"cat":"Ping/Trace","code":"ping","desc":"Extended ping (interaktif mod). Protocol, target, repeat, size, timeout, source, DF-bit, sweep, data pattern, validate reply secenekleri sunulur","sev":"i"},{"cat":"Ping/Trace","code":"ping vrf <name> <ip>","desc":"VRF icinden ping. Global routing tablosu yerine belirtilen VRF'in tablosunu kullanir. MPLS L3VPN testi","sev":"i"},{"cat":"Ping/Trace","code":"traceroute <ip>","desc":"Hedefe giden her hop'u gosterir. * = timeout (ICMP filtrelenmis olabilir). Son hop'a kadar gitmiyor = routing/ACL sorunu","sev":"i"},{"cat":"Ping/Trace","code":"traceroute <ip> source <source-ip-or-intf>","desc":"Kaynak belirterek traceroute. VPN/loopback uzerinden yol tespiti icin","sev":"i"},{"cat":"Ping/Trace","code":"traceroute","desc":"Extended traceroute (interaktif). Target, source, numeric, timeout, probe count, min/max TTL, port number secenekleri","sev":"i"},{"cat":"Ping/Trace","code":"traceroute <ip> port <port>","desc":"Belirli UDP port ile traceroute. Firewall'da belirli portun engellendigi yeri bulmak icin","sev":"i"},{"cat":"Ping/Trace","code":"traceroute <ip> ttl <min> <max>","desc":"TTL araligini belirle. min=baslangic hop, max=son hop. Belirli hop araligini incelemek icin","sev":"i"},{"cat":"Ping/Trace","code":"traceroute vrf <name> <ip>","desc":"VRF icinden traceroute. MPLS L3VPN yol tespiti","sev":"i"},{"cat":"Ping/Trace","code":"show ip cef <ip>","desc":"CEF forwarding tablosunda belirli IP'nin cikis interface/next-hop'unu goster. Paket nereye gider?","sev":"i"},{"cat":"Ping/Trace","code":"show ip cef","desc":"CEF FIB tablosu: prefix, next-hop, interface. Process switching yerine CEF kullanildigini dogrula","sev":"i"},{"cat":"Debug","code":"debug ip packet","desc":"IP paket isleme debug. CPU YOGUN! ACL ile filtreleyin: debug ip packet <acl> detail. Her paketi gosterir","sev":"e"},{"cat":"Debug","code":"debug ip packet <acl> detail","desc":"ACL ile filtrelenmis IP debug. Sadece ACL'ye uyan paketler gosterilir. Production'da guvenli kullanim","sev":"w"},{"cat":"Debug","code":"debug ip icmp","desc":"ICMP mesajlari: echo/reply/unreachable/redirect/time-exceeded. Ping sorunlari icin","sev":"i"},{"cat":"Debug","code":"debug ip routing","desc":"Routing tablosu degisiklikleri: route ekleme/silme. Routing instability/flapping teshisi","sev":"w"},{"cat":"Debug","code":"debug arp","desc":"ARP islemleri: request/reply gonderme/alma. IP-MAC cozumleme sorunlari. Proxy-ARP davranisi","sev":"i"},{"cat":"Debug","code":"debug ip nat","desc":"NAT ceviri islemleri: hangi IP:port hangi IP:port'a cevriliyor. NAT troubleshooting icin","sev":"i"},{"cat":"Debug","code":"debug ip nat detailed","desc":"NAT detayli: translation create/delete, ALG (Application Layer Gateway) bilgisi","sev":"w"},{"cat":"Debug","code":"debug ip ospf adj","desc":"OSPF adjacency olaylari: state transition, DR/BDR election, hello/dead timer mismatch tespiti","sev":"w"},{"cat":"Debug","code":"debug ip ospf hello","desc":"OSPF Hello paketleri: alinan/gonderilen. Timer mismatch, area mismatch, auth hatasi teshisi","sev":"i"},{"cat":"Debug","code":"debug ip ospf events","desc":"OSPF olaylari: SPF hesaplama, LSA flooding, neighbor state degisiklikleri","sev":"w"},{"cat":"Debug","code":"debug eigrp packets","desc":"EIGRP paketleri: Hello, Update, Query, Reply, ACK. Neighbor sorunlari, SIA teshisi","sev":"w"},{"cat":"Debug","code":"debug eigrp neighbors","desc":"EIGRP neighbor olaylari: adjacency kurulma/kopma, K-value mismatch, AS mismatch","sev":"i"},{"cat":"Debug","code":"debug ip bgp","desc":"BGP olaylari: state transitions, UPDATE/NOTIFICATION mesajlari. Peer sorunlari","sev":"w"},{"cat":"Debug","code":"debug ip bgp updates","desc":"BGP update mesajlari: alinan/gonderilen prefix ve attribute'lar. Route filtreleme kontrolu","sev":"w"},{"cat":"Debug","code":"debug ip bgp keepalives","desc":"BGP keepalive mesajlari: timer izleme. Session timeout sorunlari","sev":"i"},{"cat":"Debug","code":"debug crypto isakmp","desc":"IKE Phase 1 debug: SA negotiation, auth, DH exchange. VPN tunnel kurulumu izleme","sev":"w"},{"cat":"Debug","code":"debug crypto ipsec","desc":"IKE Phase 2 debug: IPsec SA negotiation, transform-set match. Proxy identity kontrolu","sev":"w"},{"cat":"Debug","code":"debug standby","desc":"HSRP olaylari: state transition (Active/Standby), priority change, preemption","sev":"i"},{"cat":"Debug","code":"debug standby terse","desc":"HSRP ozet debug: daha az cikti. State degisiklikleri. Production'da tercih edin","sev":"i"},{"cat":"Debug","code":"debug spanning-tree events","desc":"STP olaylari: topology change, root election, port state transition. Loop/convergence sorunlari","sev":"i"},{"cat":"Debug","code":"debug spanning-tree bpdu","desc":"STP BPDU paketleri: gonderilen/alinan BPDU icerik detaylari","sev":"w"},{"cat":"Debug","code":"debug etherchannel","desc":"EtherChannel olaylari: port ekleme/cikarma, protocol negotiation. Port-channel sorunlari","sev":"i"},{"cat":"Debug","code":"debug lacp all","desc":"LACP tum olaylar: packet, event, state machine. Port-channel suspend/individual sorunlari","sev":"w"},{"cat":"Debug","code":"debug ip dhcp server events","desc":"DHCP server: DISCOVER, OFFER, REQUEST, ACK/NAK mesajlari. Client IP alamiyor teshisi","sev":"i"},{"cat":"Debug","code":"debug mpls ldp messages sent","desc":"LDP gonderilen mesajlar: label mapping/request/withdraw. MPLS label sorunlari","sev":"w"},{"cat":"Debug","code":"debug condition interface <intf>","desc":"Debug ciktisini belirli interface ile sinirla. Diger interface'lerin debug ciktisi bastirilir. Production best practice","sev":"i"},{"cat":"Debug","code":"undebug all","desc":"TUM debug'lari kapat. Kisaltma: u all. Debug sonrasi MUTLAKA calistirin! 'no debug all' da ayni isi yapar","sev":"ok"},{"cat":"Debug","code":"terminal monitor","desc":"VTY session'da debug/log ciktisini gormeyi etkinlestir. SSH/Telnet uzerinden debug icin GEREKLI. Console'da otomatik","sev":"i"},{"cat":"Debug","code":"terminal no monitor","desc":"VTY'de debug ciktisini kapat. Debug bitince calistirin","sev":"ok"},{"cat":"SPAN","code":"monitor session <id> source interface <intf> both","desc":"SPAN kaynak: bu interface'in trafigini mirror et. both=rx+tx, rx=sadece gelen, tx=sadece giden","sev":"i"},{"cat":"SPAN","code":"monitor session <id> source vlan <id>","desc":"VSPAN: VLAN bazli mirror. Belirli VLAN'daki tum trafigi yakala","sev":"i"},{"cat":"SPAN","code":"monitor session <id> destination interface <intf>","desc":"SPAN hedef port: capture cihazi (laptop/wireshark) bu porta baglanir. Port normal switch fonksiyonu kaybeder!","sev":"i"},{"cat":"SPAN","code":"monitor session <id> filter vlan <vlan-list>","desc":"Trunk kaynak portta VLAN filtresi. Sadece belirli VLAN trafigini yakala","sev":"i"},{"cat":"SPAN","code":"show monitor","desc":"Tum SPAN session'lari: source, destination, direction, filter, status","sev":"i"},{"cat":"SPAN","code":"no monitor session <id>","desc":"SPAN session sil. Bitince temizleyin — SPAN CPU/bandwidth kullanir","sev":"ok"},{"cat":"Storm Control","code":"storm-control broadcast level 20.00 10.00","desc":"Broadcast storm koruma: %20 esik asildinda trafik durdur, %10'a dusunce tekrar ac. Interface altinda","sev":"i"},{"cat":"Storm Control","code":"storm-control multicast level 20.00","desc":"Multicast storm koruma. Esik asildinda multicast trafik engellenir","sev":"i"},{"cat":"Storm Control","code":"storm-control action shutdown","desc":"Esik asilirsa portu err-disable yap. Default: sadece filtre/drop. shutdown = daha agresif","sev":"w"},{"cat":"Storm Control","code":"show storm-control","desc":"Storm control durumu: trafik tipi, esik, aksiyon, mevcut seviye","sev":"i"},{"cat":"DAI","code":"ip arp inspection vlan <vlan-range>","desc":"DAI (Dynamic ARP Inspection) etkinlestir. ARP spoofing korunmasi. DHCP snooping binding DB'ye dayanir","sev":"i"},{"cat":"DAI","code":"ip arp inspection trust","desc":"Interface'i DAI trusted yap. Uplink portlarda kullanin. Untrusted portlarda ARP dogrulanir","sev":"i"},{"cat":"DAI","code":"show ip arp inspection","desc":"DAI durumu ve istatistikleri: forwarded/dropped ARP sayilari. Dropped yuksekse ARP sorunu var","sev":"i"},{"cat":"Monitoring","code":"show processes cpu sorted","desc":"CPU tuketimi yuksekten dusuge: process ismi, 5sn/1dk/5dk ortalamasi. Hangi process CPU yiyor? Yuksek CPU teshisi","sev":"i"},{"cat":"Monitoring","code":"show processes cpu history","desc":"CPU kullanim grafigi: son 60sn, 60dk, 72saat. ASCII graf. Trend analizi — CPU ne zaman yukseldi?","sev":"i"},{"cat":"Monitoring","code":"show processes memory sorted","desc":"Memory kullanimi yuksekten: process, allocated, freed, holding. Memory leak teshisi","sev":"i"},{"cat":"Monitoring","code":"show logging","desc":"Syslog buffer: timestamp, severity, facility, mesaj. Hata teshisinde ILK bakilacak yer. Son loglar altta","sev":"i"},{"cat":"Monitoring","code":"show environment all","desc":"Cevre durumu: sicaklik, fan hizi, guc kaynaklari, voltaj. Hardware sorunu kontrolu. CRITICAL alanlara dikkat","sev":"i"},{"cat":"Monitoring","code":"show platform","desc":"Platform bilgisi: TCAM kullanimi, forwarding engine, port ASIC. Hardware seviye sorunlar icin","sev":"i"},{"cat":"Monitoring","code":"show ip traffic","desc":"IP protokol istatistikleri: ICMP/TCP/UDP/BGP/OSPF/ARP gonderilen/alinan/drop sayilari. Trafik profili","sev":"i"},{"cat":"Monitoring","code":"show buffers","desc":"Buffer havuz bilgisi: Small/Middle/Big — total, free, hits, misses. Misses yuksekse buffer tukeniyor","sev":"i"},{"cat":"Monitoring","code":"show power inline","desc":"PoE durumu: tum portlarin guc tuketimi (W), sinif, max, toplam kullanilan/kalan. IP phone/AP beslemesi kontrolu","sev":"i"},{"cat":"Monitoring","code":"show power inline <intf>","desc":"Belirli portun PoE detayi: device, class, watts, status (on/off/faulty)","sev":"i"},{"cat":"Monitoring","code":"show interfaces err-disabled","desc":"Err-disabled portlar: neden kapatildi (bpduguard/port-security/storm-control/UDLD). shutdown/no shutdown ile ac","sev":"w"},{"cat":"VRF","code":"show ip vrf","desc":"VRF listesi: isim, default RD, iliskili interface'ler. Multi-tenant routing kontrolu","sev":"i"},{"cat":"VRF","code":"show ip vrf detail","desc":"VRF detay: RD, RT import/export, interface listesi, address family","sev":"i"},{"cat":"VRF","code":"show ip route vrf <name>","desc":"VRF routing tablosu. Global tablodan BAGIMSIZ. MPLS L3VPN troubleshooting","sev":"i"},{"cat":"VRF","code":"show ip arp vrf <name>","desc":"VRF'e ait ARP tablosu","sev":"i"},{"cat":"Multicast","code":"show ip mroute","desc":"Multicast routing tablosu: (S,G) ve (*,G) entry'leri, incoming/outgoing interface, RPF neighbor","sev":"i"},{"cat":"Multicast","code":"show ip igmp groups","desc":"IGMP ile ogrenilen multicast grup listesi: group IP, interface, uptime","sev":"i"},{"cat":"Multicast","code":"show ip pim neighbor","desc":"PIM neighbor listesi: IP, interface, uptime, DR priority","sev":"i"},{"cat":"NX-OS","code":"show checkpoint summary","desc":"Checkpoint listesi: isim, zaman, boyut","sev":"i"}],"scenarios":[{"title":"IPsec VPN Tunnel Down","severity":"err","symptom":"VPN tunnel kurulmuyor, trafik sifrelenmiyorsa.","steps":[{"code":"show crypto isakmp sa","desc":"IKE Phase 1 SA durumu: QM_IDLE=basarili, MM_NO_STATE=basarisiz"},{"code":"show crypto ipsec sa","desc":"IPsec Phase 2 SA: encaps/decaps sayilari, transform-set, SPI"},{"code":"show crypto session","desc":"Session durumu: UP-ACTIVE/DOWN"},{"code":"debug crypto isakmp","desc":"Phase 1 debug: PSK mismatch, policy mismatch, peer unreachable"},{"code":"debug crypto ipsec","desc":"Phase 2 debug: transform mismatch, proxy identity (ACL) mismatch"},{"code":"show crypto isakmp policy","desc":"Tanimli policy'leri kontrol et: encryption, hash, DH group eslesmeli"}]},{"title":"NAT Calismiyorsa","severity":"err","symptom":"NAT ceviri yapilmiyor, ic agdan internete cikilamiyor.","steps":[{"code":"show ip nat translations","desc":"Aktif NAT ceviri tablosu. Bossa = ceviri yapilmiyor"},{"code":"show ip nat statistics","desc":"NAT istatistikleri: hit/miss sayisi. Miss yuksekse ACL sorunu"},{"code":"show ip interface brief","desc":"Interface'lerde ip nat inside/outside dogru mu?"},{"code":"show access-lists <nat-acl>","desc":"NAT ACL'ini kontrol et: dogru subnet tanimli mi?"},{"code":"debug ip nat","desc":"NAT isleme debug: paket neden cevirilmiyor?"}]},{"title":"EtherChannel / Port-Channel Down","severity":"err","symptom":"Port-channel olusmuyor veya member portlar standalone gorunuyor.","steps":[{"code":"show etherchannel summary","desc":"EtherChannel ozeti: flag'lar P=bundled, I=standalone, s=suspended, D=down"},{"code":"show etherchannel detail","desc":"Detayli bilgi: neden bundle olamadigi"},{"code":"show lacp neighbor","desc":"LACP komsuluk: karsi taraf bilgileri, state flags"},{"code":"show lacp counters","desc":"LACP PDU sayaclari: sent/received. 0=protokol calismiyor"},{"code":"show interfaces status","desc":"Fiziksel port durumu: speed, duplex eslesmeli"}]},{"title":"NX-OS vPC Consistency Check Basarisiz","severity":"err","symptom":"vPC port'lari suspended, consistency check hata veriyor.","steps":[{"code":"show vpc","desc":"vPC genel durumu: peer status, consistency status"},{"code":"show vpc consistency-parameters global","desc":"Global parametrelerin eslesmesi: STP mode, VLAN, MTU"},{"code":"show vpc consistency-parameters interface port-channel<id>","desc":"Interface bazli consistency: trunk mode, allowed VLAN"},{"code":"show vpc peer-keepalive","desc":"Peer-keepalive status: alive olmali"},{"code":"show run vpc","desc":"vPC konfigurasyonunu kontrol et"}]},{"title":"QoS Policy Calismiyorsa","severity":"warn","symptom":"QoS policy uygulanmiyor, trafik onceliklendirilmiyorsa.","steps":[{"code":"show policy-map interface <interface>","desc":"Interface'te QoS istatistikleri: match/drop sayilari"},{"code":"show class-map","desc":"Class-map konfigurasyonunu kontrol et"},{"code":"show policy-map","desc":"Policy-map konfigurasyonunu kontrol et"},{"code":"show mls qos","desc":"Global QoS etkin mi? (Catalyst switchlerde)"},{"code":"show running-config | section policy-map","desc":"QoS konfig kontrolu"}]},{"title":"DHCP IP Alamiyor","severity":"err","symptom":"Client DHCP ile IP adresi alamiyor.","steps":[{"code":"show ip dhcp pool","desc":"DHCP pool durumu: kac adres dagitilmis, kac bos"},{"code":"show ip dhcp binding","desc":"Dagitilmis IP listesi"},{"code":"show ip dhcp conflict","desc":"IP catismalari var mi?"},{"code":"show ip dhcp server statistics","desc":"DHCP mesaj sayaclari: DISCOVER var ama OFFER yoksa = pool sorunu"},{"code":"debug ip dhcp server events","desc":"DHCP olaylarini debug et"},{"code":"show running-config | include helper","desc":"ip helper-address dogru mu?"}]},{"title":"BGP Neighbor Established Olmuyorsa","severity":"err","symptom":"BGP neighbor Idle, Active veya Connect durumunda takili kaliyor.","steps":[{"code":"show ip bgp summary","desc":"Neighbor state kontrol: Idle/Active/Connect = SORUN"},{"code":"show ip bgp neighbors <ip>","desc":"Detayli neighbor bilgisi: son hata mesaji, notifications"},{"code":"show tcp brief","desc":"BGP TCP 179 session kurulmus mu?"},{"code":"show ip route <neighbor-ip>","desc":"Neighbor IP'sine route var mi?"},{"code":"show access-lists","desc":"TCP 179 engelleyen ACL var mi?"},{"code":"show ip interface <intf>","desc":"Interface'te ACL uygulanmis mi?"}]},{"title":"OSPF Neighbor Full Olmuyorsa","severity":"err","symptom":"OSPF neighbor Init, 2-Way veya Exstart'ta takili kaliyor.","steps":[{"code":"show ip ospf neighbor","desc":"Neighbor state kontrol: Full=OK, Init/Exstart=SORUN"},{"code":"show ip ospf interface <intf>","desc":"Hello/Dead timer, area, network type kontrol"},{"code":"show ip ospf","desc":"Router ID catismasi var mi?"},{"code":"show ip ospf neighbor detail","desc":"Detayli bilgi: retransmit, state transition sayisi"},{"code":"debug ip ospf hello","desc":"Hello paketlerini debug et (dikkatli!)"}]},{"title":"STP Loop / Err-Disable Sorunu","severity":"err","symptom":"Port err-disable'a dusuyor veya network'te loop var.","steps":[{"code":"show interfaces status","desc":"Err-disabled portlari bul"},{"code":"show spanning-tree","desc":"STP durumu: blocking portlar, root bridge"},{"code":"show spanning-tree blockedports","desc":"Hangi portlar STP tarafindan block edilmis?"},{"code":"show spanning-tree inconsistentports","desc":"STP inconsistency var mi?"},{"code":"show errdisable recovery","desc":"Otomatik recovery ayarlari"},{"code":"show log | include err-disable","desc":"Err-disable sebebini log'da bul"}]},{"title":"HSRP Failover Calismiyorsa","severity":"warn","symptom":"HSRP Active router down oldugunda Standby devralmiyor.","steps":[{"code":"show standby brief","desc":"HSRP durumu: her iki router'da Active/Standby/Init kontrol"},{"code":"show standby","desc":"Detayli HSRP bilgisi: priority, preempt, timers, virtual IP"},{"code":"show standby <intf> <grp>","desc":"Belirli interface/grup detayi"}]}],"sources":{},"links":[{"name":"networktocode/ntc-templates","url":"https://github.com/networktocode/ntc-templates","desc":"TextFSM template'leri: Cisco show komut ciktilarini structured data'ya cevir."},{"name":"ktbyers/netmiko","url":"https://github.com/ktbyers/netmiko","desc":"Netmiko: SSH ile network cihaz otomasyonu. 100+ platform destegi. Python."},{"name":"napalm-automation/napalm","url":"https://github.com/napalm-automation/napalm","desc":"NAPALM: multi-vendor network automation. IOS, NX-OS, Junos. Python."},{"name":"nornir-automation/nornir","url":"https://github.com/nornir-automation/nornir","desc":"Nornir: Python network automation framework. Ansible alternatifi."},{"name":"batfish/batfish","url":"https://github.com/batfish/batfish","desc":"Batfish: network config analizi ve pre-deployment validation."},{"name":"CiscoDevNet/yang-explorer","url":"https://github.com/CiscoDevNet/yang-explorer","desc":"YANG model explorer: NETCONF/RESTCONF icin."},{"name":"cisco-config-analysis-tool/ccat","url":"https://github.com/cisco-config-analysis-tool/ccat","desc":"CCAT: Cisco config analiz araci. Security best practice kontrolu."},{"name":"r7perezyera/Cisco-IOS-Command-CheatSheets","url":"https://github.com/r7perezyera/Cisco-IOS-Command-CheatSheets","desc":"Switch/router komut cheat sheet. CCNA topics."},{"name":"Cisco IOS Command Reference","url":"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/fundamentals/command/cf_command_ref.html","desc":"Resmi Cisco IOS komut referansi."},{"name":"PacketLife.net Cheat Sheets","url":"https://packetlife.net/library/cheat-sheets/","desc":"OSPF, BGP, VLANs, QoS, IOS, IPsec PDF cheat sheet'ler."},{"name":"NetworkLessons.com","url":"https://networklessons.com/","desc":"Kapsamli Cisco network dersleri."},{"name":"Cisco Learning Network","url":"https://learningnetwork.cisco.com/","desc":"Cisco sertifikasyon platformu."},{"name":"cmdref.net Cisco","url":"https://cmdref.net/","desc":"Hizli CLI referansi — IOS/NX-OS orneklerle."},{"name":"Cisco Config Guides","url":"https://www.cisco.com/c/en/us/support/ios-nx-os-software/ios-15-4m-t/products-installation-and-configuration-guides-list.html","desc":"Resmi IOS yapilandirma kilavuzlari."}]};
